INSERT INTO `locales_quest` (`entry`, `Details_loc4`) VALUES (41641, 'Akamagosh，$C。我们用来与灵魂沟通的圣地——大地之环，曾被一大群风元素占据，肆意肆虐。所幸我的同伴Zoluuli和Tectonius在勇敢的萨满冒险者的帮助下，把它们驱逐了出去。如今许多成员已经从为修补这个病痛的世界与失衡的秩序而进行的朝圣中归来，我们可以再次专注于平息元素的躁动。$B$B既然你就在这儿，你的帮助会大受欢迎。大地之灵对我低语，告诉我那些被我们赶走的元素仍留在石爪山这里，正暗中谋划。我们必须彻底挫败他们的野心，好专心处理眼前的事务。灵魂们告诉我一个地方，就在石爪峰西北方的一条山道上。留意在那里筑巢的巨鹰；一旦看到它们，你就知道自己快到了。') ON DUPLICATE KEY UPDATE `Details_loc4` = VALUES(`Details_loc4`);
INSERT INTO `locales_quest` (`entry`, `Details_loc4`) VALUES (41662, '有人或许以为，从暴风城前往北风领会是一段惬意的旅程，不过是林中散步——而不是被一群嗜血、流着口水的豺狼人追着跑。$$B自从国王踏上外交使命以来，情况只会越来越糟。我们竟然连自己的卫兵都指望不上，简直难以置信！我们不得不从平民中拉起一支民兵。这真是可悲。$B$B唉，可贵族议会里那些该死的贪婪蠢猪还在伸手要税。我——请原谅我失态。在来这儿的路上，我为了逃命，把那枚珍爱的戒指从手指上弄掉了！$B$B我的货物丢了，那就算了。可那枚戒指，我良心上实在舍不得；它是祖传的宝物。它一定是掉在商旅之路上的某堆落叶里了。你能好心帮我把它找回来吗？') ON DUPLICATE KEY UPDATE `Details_loc4` = VALUES(`Details_loc4`);
INSERT INTO `locales_quest` (`entry`, `Details_loc4`) VALUES (41804, 'Skardyn……拥有可怕力量与暗影怒火的生物。他们远比你强大，凡人，也比任何一支寻常的冒险者队伍强大得多。与他们正面交锋是愚蠢之举。他们的皮肉由浸透邪恶法术的鳞甲守护，形体被深深织入他们本质的诅咒所庇护。$B$B若想有一线胜机，我们就得锻造一件武器，一件能刺穿他们黑暗结界的武器。但我必须坦白，凡人……即便以我全部学识，我也不知道那该是件什么样的武器。他们覆灭的秘密超出了我的掌握。$B$B不过，或许还有另一条路。Skardyn原本是黑铁矮人，虽被暗影扭曲，但毕竟曾与那些仍在地表行走的人同族。也许他们的后裔还保留着关于那些受诅咒亲族遭遇的记载。$B$B你必须去荒芜之地的苦痛堡垒。黑铁矮人仍在那里逗留，他们离群索居、神秘莫测，而且危险。格瑞姆巴托地底究竟发生了什么，真相就在那里。') ON DUPLICATE KEY UPDATE `Details_loc4` = VALUES(`Details_loc4`);
INSERT INTO `locales_quest` (`entry`, `Details_loc4`) VALUES (41906, '$n，他们和我们猎杀的野兽没什么两样。我的族人历尽苦难，黑铁矮人却不肯让他们找到新的家园，就此破坏了我们的安宁。他们不仅伏击我们前往铁炉堡的商队，最近还开始绑架无辜者。$B$B$n，你愿意帮我们救出这些可怜人吗？我不敢去想那些矮人打算对他们做什么，毕竟被掳走的人里甚至还有一个孩子。难道真像那些山民说的那样，他们会被送去黑石山的深矿里做苦役？真到了那一步，他们活不下来的。$B$B求你了，让他们在米奈希尔的圣战带来的恐怖之后，还能有机会迎来更光明的未来。把他们从牢里放出来吧，我敢肯定某个黑铁矮人身上带着牢门的钥匙。$B$B他们被带去了西南方的营地。') ON DUPLICATE KEY UPDATE `Details_loc4` = VALUES(`Details_loc4`);
INSERT INTO `locales_quest` (`entry`, `Details_loc4`) VALUES (41911, '自从Fallen Ones把我们困在村子里，我们就一直密切注视着他们的动向。他们当中一些人游荡在闪星湖沿岸的外围，而大部分兵力则从北面袭击我们。遗憾的是，他们的侵犯并不只针对我们。他们已经开始伏击当地的牛头人，甚至洗劫了其中一个村庄，这些你或许已经知道了。这不禁让人发问：他们到底想要什么？$B$B我们首先需要的是情报。Narlan是我们的一名猎手，也是我的挚友，他自愿潜入他们在河角村以东建立的前哨据点。他假扮成我们部族的叛逃者，已经给我们传回了不少宝贵的情报。他最后一份报告提到他正在追查一条危险的线索，此后我们就再没听到他的消息。理智上我早已接受了可能的结局，可我的心却仍盼着那并非事实。去Fallen Ones的前哨据点搜寻Narlan吧。如果有必要，就替他完成他未竟的事情。') ON DUPLICATE KEY UPDATE `Details_loc4` = VALUES(`Details_loc4`);
INSERT INTO `locales_quest` (`entry`, `Details_loc4`) VALUES (41914, '<Ralpekta面色严峻，一滴汗珠顺着他橄榄色皮肤的皱纹滑落。>$B$B我曾透过虚空窥视，看到了那枚红色水晶的根源。当我专注于这次占卜时，可怕的景象掠过我的脑海。高壮的生灵长着蹄子和利爪，行走在血红色的峡谷中，他们中间还有德莱尼人，携带着我们神圣的德拉诺水晶。这些长蹄的怪物……它们的犄角和毛发让我想起扭曲虚空的恶魔，那些多年前在德拉诺奴役了兽人的恐怖存在。Parashka，往北去吧，越过河角村。在那里，山峦的另一边，你应该能找到我所窥见的东西。无论你找到什么，都不会是友善的。$B$B年轻的Arlia把你送到我这里来是对的。他把父亲的教诲记在了心里，尽管他自己还没有察觉。作为他的导师，我知道他要学的还很多。等你找到这些异端的罪魁祸首，就把他们已死的证据带给Arlia。他应该会在集市上等你。') ON DUPLICATE KEY UPDATE `Details_loc4` = VALUES(`Details_loc4`);
INSERT INTO `locales_quest` (`entry`, `Details_loc4`) VALUES (41915, '这封信里 Bhurobi 谈到的那位新神……我们德莱尼从不向任何神明祈祷，我们敬拜的是德莱尼水晶的壮丽，它是我们母星生命之血的象征。要说有德莱尼会把自己奉献给某一个存在，直说吧，这实在让人费解。$B$B父亲一定知道那位长者已经背弃了对德莱尼水晶的信仰，他一定知道。$N，我们该拿查到的东西去当面对质。也许能说服他说出真相。你先去，我随后就到。') ON DUPLICATE KEY UPDATE `Details_loc4` = VALUES(`Details_loc4`);
INSERT INTO `locales_quest` (`entry`, `Details_loc4`) VALUES (41916, 'Bhurobi离开的那天，他和追随者们一路向北而去。河角村以东的那个前哨据点建立还没多久，这说明他们一定在更北的地方定居了下来。$C，我们德莱尼人习惯傍水而居；即便Bhurobi背弃了我们的传统，我确信他仍会遵循这种直觉。这片海岸的北部平原上有一座浅湖，你很可能会在那里找到他们，正在向他们虚假的神明布道。$B$B等你找到他们的圣所，就去找到Bhurobi，终结他的恐怖行径。恐怕他已经无可挽救了。至于他的追随者，请尽可能多地放过他们。我不会要求你不还手，但他们是被虚假的希望所误导。假以时日，他们会找回回归我们中间的路，我和其他长者会确保这一点。') ON DUPLICATE KEY UPDATE `Details_loc4` = VALUES(`Details_loc4`);
INSERT INTO `locales_quest` (`entry`, `Details_loc4`) VALUES (41920, '真是一桩接一桩的倒霉事！先是那些该死的Fallen Ones在林子周围游荡，害我不得不绕路，现在我的货车又坏了，我只能在这露天的地方修它。更别提我放在车上的一批重要货物，已经在东边的森林里弄丢了。$B$B像你这样强壮的冒险者，也许正好能把我从这苦日子里救出来。请往东走一趟，找到我从Fallen Ones手里逃出来时从车上掉下去的那只木箱。他们是群强盗，是抛弃了我们部族的残暴德莱尼，我毫不怀疑他们也会攻击你。要是运气不好，他们可能已经把箱子抢走了。如果你找到了，就把它送到北边闪星湖畔我们村里的Pli那里。告诉他是我Maghan叫你去的，我很快就回来。') ON DUPLICATE KEY UPDATE `Details_loc4` = VALUES(`Details_loc4`);
INSERT INTO `locales_quest` (`entry`, `Details_loc4`) VALUES (41928, '<地穴领主倒在你脚边，死透了。这从诺森德冰层深处爬出来的恶魔再也不能在生者之间散播恐惧。可你手里握着的东西，却让你这老练的冒险者本能地感到不安。石板触手冰寒，里面还能听见隐约的低语。单凭你一个人的力量打不碎它，也驱不散那股邪恶气息。也许一位强大的圣光使用者能在这种时候帮上你。>') ON DUPLICATE KEY UPDATE `Details_loc4` = VALUES(`Details_loc4`);
INSERT INTO `locales_quest` (`entry`, `Details_loc4`) VALUES (41930, '你正站在Narkogg the Dark面前——乌索兰仅存的木喉部族的代言人。我和同胞们已被打得四分五裂，濒临灭绝。黑暗降临木喉要塞，面对从大门里涌出的腐化之潮，我们无能为力。若想清除那里的污秽，我们迫切需要盟友。你和你这样的种族，愿意帮助我们完成这项事业吗？为此，我需要证据。$B$B进入我们昔日家园的隧道，突破那道关口。杀死Karrsh the Sentinel——他曾是自豪的守卫者，如今却成了只求流血的疯狂野人。必须制止他的暴行。') ON DUPLICATE KEY UPDATE `Details_loc4` = VALUES(`Details_loc4`);
INSERT INTO `locales_quest` (`entry`, `Details_loc4`) VALUES (41931, '我们守望荒野的职责自古便已存在，但自从燃烧军团第二次入侵以来，一种邪恶的病症就在我们最神圣的圣地里滋生。我们的族人一个接一个被那恶毒的影响吞噬。如今只剩下我们，解放木喉要塞、使它脱离邪恶掌控的重任就落在我们肩上。在彻底净化家园之前，我们得先弄清对手究竟是什么。在洞窟里研究它实在太危险，所以我们需要替代品。$B$B回到木喉要塞，收集那些误入歧途的萨满的图腾，有了它们，我们就能找到对抗这折磨我族人的病症的办法。') ON DUPLICATE KEY UPDATE `Details_loc4` = VALUES(`Details_loc4`);
INSERT INTO `locales_quest` (`entry`, `Details_loc4`) VALUES (41932, '我们在卡利姆多生活了数千年，我的族人配出过无数药剂和药膏，用来治疗伤病、抚慰灵魂。可要净化那些邪恶的图腾，非得配出一味全新的药不可。$B$B在被荒野祝福的土地上——你们称之为安戈洛环形山——住着一头叫 Rotvine 的野兽，它浑身都是自然之力，露水充盈。据说它的家在西北方河流的尽头。把它那颗浸满露水的心脏带给我。$B$B在菲拉斯恐怖之岛的南岸，你还找到一位远古的存在，一名上古时代的海巨人。他曾守望迷雾之海的潮汐，可如今他的心智已经分不清敌友。让他安息，把他的舌头带给我。$B$B净化之瓶在 Tidelord Rrurgaz 手上。它曾是上古卡利姆多暗夜精灵的圣物，后来落到 Shahraz 纳迦手中——他们正在奥卡兹岛上谋划，那岛就在尘泥沼泽海岸的东北方。') ON DUPLICATE KEY UPDATE `Details_loc4` = VALUES(`Details_loc4`);
INSERT INTO `locales_quest` (`entry`, `Details_loc4`) VALUES (41933, '看来我低估了Withermaw。附着在这些图腾里的东西并不只有恶魔的来头。恐怕我们手上的东西不足以打破它们身上的诅咒。$B$B$N，要想成功，我们得再闯一次木喉要塞。在Timbermaw Village深处，坐落着Grotto of Dreams。那里从前是我们部族通灵师与翡翠梦境沟通的地方，如今却盘踞着险恶的瘴气。我们逃离旧日家园时，我把我的药袋落在了那里。我需要里面的法器来施行更合适的法术。此外，还需要一份从木喉要塞里取得的污秽样本。把它混入药膏，就能成为图腾内咒力的解药——如果你愿意这么理解的话。你肯定能在里面水道沿岸的众多裂隙中找到这样的样本。') ON DUPLICATE KEY UPDATE `Details_loc4` = VALUES(`Details_loc4`);
INSERT INTO `locales_quest` (`entry`, `Details_loc4`) VALUES (41934, '$N，你对我族事业的忠诚与决心无可限量。你以非凡的勇气直面扭曲的Withermaw，挫败了他们的阴谋。你与你的盟友所展现的力量与意志，正是我之所以要把这件不可能之事托付给你的原因。$B$B如我先前所言，木喉要塞是所有熊怪的神圣之地。我们在那里敬奉荒野之神乌索尔的遗骸；自他在上古之战中死于燃烧军团之手后，我们已守护其遗骸数千年之久。Withermaw占据那里时，我并不在他的安息之地，但我担心这位远古守护者的遗体也已沦为腐化的牺牲品。$B$B我们勇敢的盟友，请重返木喉要塞，看看我们伟大的神明如今变成了什么模样。倘若污秽已控制了他的躯壳，那么……聚起你的力量，让他重新回归翡翠梦境吧。') ON DUPLICATE KEY UPDATE `Details_loc4` = VALUES(`Details_loc4`);
INSERT INTO `locales_quest` (`entry`, `Details_loc4`) VALUES (41935, '你找到的石板散发着古老的力量。它笼罩在令人望而生畏的气息之中，你猜想这一定是往昔岁月的遗物，不知怎么落到了管理者埃克索图斯的手中。细读其内容，可以看到上面以符文和刻记描述着一道强大的复活法术，用以复活不朽的存在。所需的只是诵出上面的词句，再加上你希望重新锚定于凡间的那个存在的精华。$B$B冒险与劫掠带来的兴奋仍未平息，你不禁琢磨，能否用这件神器为自己谋取私利……') ON DUPLICATE KEY UPDATE `Details_loc4` = VALUES(`Details_loc4`);
INSERT INTO `locales_quest` (`entry`, `Details_loc4`) VALUES (41936, '水晶发出不祥的嗡鸣。透过它光洁无瑕的表面望进去，仿佛有一团翻涌的漩涡藏在宝石内部。它触手冰冷，重得出奇，你能感到一股阴暗可怕的力量从无尽虚空的深处向你招手。你既着迷又震惊，决定把它带去给一位强大的术士，也许他能帮上忙。') ON DUPLICATE KEY UPDATE `Details_loc4` = VALUES(`Details_loc4`);
INSERT INTO `locales_quest` (`entry`, `Details_loc4`) VALUES (41939, '抱歉，我说过我能读上几段，可就算读出来也相当晦涩。上面提到了一道命令——进攻那些爱管闲事的凡人的命令。你是在一个入侵的风元素身上找到的？Greka 跟我说过我们大多数人不在时发生的事。看来这不是什么巧合，而是一场趁我们防御空虚时发动的协同进攻。再往下还有这么一句：$B$B“我会在无数尖塔林立、狂风呼啸的峡谷里等你归来。我们的长角盟友只等着成功。”$B$B$N，这可不是什么好兆头。还有别的势力在暗算大地之环，恐怕我也得弄清楚这些“长角盟友”是谁。千针石林深处有座风角峡谷，那是一座古老的石头要塞，过去曾是许多牛头部族的庇护所。如今它被 Blackwind 部族占据着，多半还有他们的元素同伙。我们必须立刻掐断这个同盟。') ON DUPLICATE KEY UPDATE `Details_loc4` = VALUES(`Details_loc4`);
INSERT INTO `locales_quest` (`entry`, `Details_loc4`) VALUES (41940, '愿众灵与你同在，朋友。我是Grakk Windtamer，大地之环的一员。确保这个世界的元素平衡不受扰乱是我们的职责。为此，我们大地之环的萨满会踏上遍布艾泽拉斯的朝圣之旅，去评估这份平衡。众灵把我引到了阿拉希高地的平原——这片土地承载着人类古老的历史，也充盈着原始的元素魔法。动荡正在地底酝酿，禁锢法阵的守护者们躁动不安。在对这座牢狱的警觉守望中，它们忘却了自己的本真——如今正在蹂躏这片高地的神圣之地。$B$B$C，帮我让它们重归安宁吧。摧毁它们的形躯，把完好的元素之核带给我，好让我平息它们体内狂暴的洪流。') ON DUPLICATE KEY UPDATE `Details_loc4` = VALUES(`Details_loc4`);
INSERT INTO `locales_quest` (`entry`, `Details_loc4`) VALUES (41941, '自然本是混沌的，$N。它不遵循任何规则，没有既定之路，也没有确定的未来。在这片混沌之中，生命在元素的滋养下萌发。土为食粮，气为呼吸，水为指引，而火既是它的养育者，也是它的毁灭者。一团火焰可以令人舒适、引人亲近，甚至用它温柔的暖意把人包裹其中。可另一方面，无边无际的烈焰又冷酷无情，不断搜寻更多生命来吞噬。$B$B火元素深深织入生与死的轮回：旧物想要重生，唯有依靠那既能毁灭、又能孕育新芽的烈焰。在卡利姆多南部的安戈洛环形山深处，这样的一体两面可以在火羽山亲眼得见。火山狂暴地毁灭一切，而土壤则从灰烬中获得新的力量。采集这种火山土壤的样本，把它们带给东瘟疫之地的雷布拉特·碎地者。他会知道该怎么处理它们。') ON DUPLICATE KEY UPDATE `Details_loc4` = VALUES(`Details_loc4`);
INSERT INTO `locales_quest` (`entry`, `Details_loc4`) VALUES (41942, '不久前许多朝圣者都回到了大地之环，我却留在了这里，为的是继续深入研究亡灵瘟疫。Far Seer Earthfury曾认为我们的被遗忘者盟友身上潜藏着治愈的可能，因此我把协助他驱除他们身上的腐朽诅咒当成了自己的使命。莱茵和我已经在治愈这片土地的死寂土壤上取得了长足进展。她是一位了不起的伙伴，我们确信一定能在这项事业中取得突破——这在很大程度上要归功于你带回来的那些土壤。$B$B不过在我们继续之前，还缺两样关键材料。首先是病木林中生长的蘑菇的孢子样本。我确信那些在废墟中游荡的亡灵骨头上就附着着这些东西。此外，还需要一株从祖玛沙尔找到的扭曲树苗。那座巨魔城市坐落在北方的群山之中。但要当心，那里的巨魔也早已屈服于亡灵瘟疫。请务必多加小心。') ON DUPLICATE KEY UPDATE `Details_loc4` = VALUES(`Details_loc4`);
INSERT INTO `locales_quest` (`entry`, `Details_loc4`) VALUES (41943, '离这里不远，凄凉之地的石谷深处有玛拉顿的殿堂。据说那里是邪恶半人马的诞生之地，是他们族人与先祖的圣地。如今这些殿堂被玷污了，扭曲成了疾病与腐臭的巢穴。这病根腐烂着土地、污染着水源，在底下的洞窟里扎下了深根，给灵魂与自然带来了巨大的痛苦。$B$B$N，我要你进入玛拉顿，摧毁那腐化的聚合体——它叫诺克赛恩。解决它之后，再除掉这一切苦难的源头，那个邪恶的萨特维利塔恩。只要他还逍遥自在，玛拉顿内部的元素就休想恢复平衡。') ON DUPLICATE KEY UPDATE `Details_loc4` = VALUES(`Details_loc4`);
INSERT INTO `locales_quest` (`entry`, `Details_loc4`) VALUES (41945, '全是这些乱七八糟的破事！谁能想到，像Bhu’robi这样的蠢货竟是一切的源头。他一直是个祸害，这蠢东西满脑子激进的想法和不切实际的妄想！你大概以为我们的酋长早就该看明白，可他被对“老朋友”的怜悯之情蒙住了眼睛。呸，随他去吧。在我眼里，Bhu’robi已经不算是德莱尼人，更别说莫洛加的一员了。$B$BParash’ka！你又害我念叨起这些！现在我的血都烧起来了，脑袋都快炸了。你得帮我治好它，臭小子！去村子东边的珀爪洞穴，给我弄些附近那些羽族的脑浆回来。我只要最黏糊的那种！') ON DUPLICATE KEY UPDATE `Details_loc4` = VALUES(`Details_loc4`);
INSERT INTO `locales_quest` (`entry`, `Details_loc4`) VALUES (41951, '请原谅我刚才的失态。我照料这些水晶已经有五百二十七个年头了，我和它们之间的联系比大多数德莱尼都要深。不过，这些水晶有件非常奇怪的事。它们被装在一只板条箱里——考虑到峡谷里那些恶魔爪牙周围到处都是被污染的水晶，这情形显得很反常。这让我相信，这些水晶本来是要被送往某处的。$B$B来，带上这只箱子，去和我们村里的商人Maghan谈谈。我相信他对这箱子知道得更多。他往村子南边去了，沿着大路走，你肯定能找到他。') ON DUPLICATE KEY UPDATE `Details_loc4` = VALUES(`Details_loc4`);
INSERT INTO `locales_quest` (`entry`, `Details_loc4`) VALUES (41953, '无论这些熊怪想用被污染的德拉诺水晶做什么，我们都不能让他们得逞。它绝不能被用于邪恶的目的，身为德莱尼人，确保这一点是我们的职责。$B$B$N，我们又一次需要你的帮助。召集勇敢的同伴，突袭熊怪的圣所。当心：他们很可能在用我们的水晶举行邪恶的仪式，也许正是借此获得了意想不到的力量。一旦查明那些被玷污的水晶的下落，就惩罚罪魁祸首，并把剩下的德拉诺水晶带回村里。我会准备好净化其中杂质的方法。') ON DUPLICATE KEY UPDATE `Details_loc4` = VALUES(`Details_loc4`);
INSERT INTO `locales_quest` (`entry`, `Details_loc4`) VALUES (41956, '你好，$C。我叫 Nathok，木喉部族的成员——或者说，是它还剩下的部分。我们被堕落的同胞 Withermaw 赶出了祖祖辈辈的家园木喉要塞。他们染上了一种可怕的黑暗，那东西在卡利姆多北部蔓延了不知多少岁月。许多人已经屈服于它，但仍有人在继续抗争。很久以前，熊怪各部族之间一直互通消息。可现在他们都沉默了，我们只能往最坏处想。$B$B我们需要知道还有哪些部族尚未沦陷，希望你能帮这个忙。在我们已知的部族里，最后的希望寄托在冬泉谷的冬泉部族、灰谷的绿爪部族，以及月光林地以南隧道中一群木喉熊怪身上。去找他们，告诉他们木喉依然是自然骄傲的守护者。') ON DUPLICATE KEY UPDATE `Details_loc4` = VALUES(`Details_loc4`);
INSERT INTO `locales_quest` (`entry`, `Details_loc4`) VALUES (41958, '不久前，乌索兰的同胞把他们的发现分享给了我们。用圣洁的药膏净化木喉要塞里的腐化，是个明智的决定。但还不够。那瘴气的真正源头就藏在深处，那东西正在卡利姆多扎根，可我们不知道它究竟是什么。恶魔沙迪维尔斯该为冬泉部族的堕落负责，可 Narkogg 形容那股腐化的感觉并不全然属于恶魔。我有个猜想，也许能让我们更接近这个谜团的答案，但为此我们需要帮助。$B$B$C，去问问伊瑟拉的巨龙军团。它们当中对我们友善的不多，但总有一些愿意听听凡人的求助。越过大海，在悲伤沼泽，有一条强大的绿龙从梦境中醒来，正等着像你我这样的凡人。也许是为了别的原因，但很可能正是为了这件事。去找它，向它打听灵魂之笛。') ON DUPLICATE KEY UPDATE `Details_loc4` = VALUES(`Details_loc4`);
INSERT INTO `locales_quest` (`entry`, `Details_loc4`) VALUES (41959, '我猜，你是想除掉木喉要塞里的黑暗？你我的利益比你以为的更一致。它被净化对我是好事，而我知道，在追查这一切根源的路上我能起到关键作用。你那位熊怪朋友猜得没错：我确实知道灵魂之笛。那是荒野诸神艾森娜的古老遗物。上古之战爆发时，卡多雷把它托付给了伊瑟拉的巨龙军团。它在那里沉睡了无数个千年，直到叛徒 Insomnius 把它偷走。他因这罪行被放逐，笛子也就此永远失落。$B$B你要想拿到它，就得找到 Insomnius。算你走运，那狡猾的东西很难杀死。他如今自称 Insom’ni。他的妄念玷污了我们守护这个世界的高贵使命，而他一心只想冒充神明统治它。你可以在 Gilijim 岛以北的岛上找到他。') ON DUPLICATE KEY UPDATE `Details_loc4` = VALUES(`Details_loc4`);
INSERT INTO `locales_quest` (`entry`, `Details_loc4`) VALUES (41961, '那感觉真叫人精神振奋。我欠你一个人情，$C，这笔债我一定会还。为了寻找易于征服的种族，我曾漫游这个世界广袤的位面，其中一处便是如今荒芜死寂的凄凉之地。遗憾的是，我没能安安静静地做自己的事——伊瑟拉的走狗一旦嗅到我的气息就会跟上来。他们追我是想夺回那支长笛。真是徒劳的挣扎。躲避追兵时，我把长笛放进了一只被魔法封印的箱子，藏在东南群山卡多雷废墟的深处，用强大的护盾遮蔽起来，让不配的人无法窥见。$B$B<英桑姆尼抓住你的手，他自己的手化作一只翡翠利爪。他用爪子在你的掌心刻下一道翠绿的符文。剧痛难忍。>$B$B现在去吧。我的耐心快要耗尽了。有了这道符文，你就能看见并打开那只箱子，取回你为之奋战的东西。') ON DUPLICATE KEY UPDATE `Details_loc4` = VALUES(`Details_loc4`);
INSERT INTO `locales_quest` (`entry`, `Details_loc4`) VALUES (41962, '你去找长笛的时候，我也做了些自己的调查。我在乌索克之喉与Narkogg会面，一起筹划了揭开腐化秘密的办法。$B$B在卡多雷种下世界之树泰达希尔的那座岛屿上，有一位年岁极为古老的远古守护者把自己的根扎进了艾泽拉斯的土地，他就是Fangorn, Lord of Eternity。他曾在那里伫立了无数纪元，永恒守望自然，即便在暗夜精灵种下泰达希尔的种子之后也是如此。像他这样古老而睿智的存在，但愿能告诉我们木喉要塞里潜藏着怎样的黑暗。$B$B带上这枚封印的图腾。用灵魂之笛唤醒那位远古守护者，把图腾给他看。出发之前，有件事你必须知道。像他这样的远古存在所说的是一种早已被遗忘的语言。你肯定听不懂他的话。我建议你去向月光林地的德鲁伊请教他的语言。') ON DUPLICATE KEY UPDATE `Details_loc4` = VALUES(`Details_loc4`);
INSERT INTO `locales_quest` (`entry`, `Details_loc4`) VALUES (41965, '你还记得我为了把恶魔沙迪维尔斯逐出冬泉酋长的洞穴而制作的那支火炬吗？如果我们想把Peroth’arn那个卑鄙的怪物从藏身处引出来，就需要再做一支那样的火炬，但威力要强大得多。为此，我们需要一簇涤罪之焰。$B$B地壳深处是熔火之心。那里遍布岩浆之河与滚烫的岩石，火元素在洞窟中彼此混战，一片混乱。而正是在那里，才能找到最纯净的火焰。只有那种强度的烈焰，才能确保我们的计划成功。$B$B把它和二十根星木原木带给我。两样都是打造足够强大的火炬所必需的。') ON DUPLICATE KEY UPDATE `Details_loc4` = VALUES(`Details_loc4`);
INSERT INTO `locales_quest` (`entry`, `Details_loc4`) VALUES (41976, '那边的，就是你，探险家！你听说过牛头人的圣谷吗？那里的房屋凿刻在岩壁之中，隧道一直通向地底。$B$B要是几周前你跟我讲这个故事，我只会笑你痴人说梦，可现在我发现这故事竟然是真的！我的一位可靠线人告诉我，千针石林里有个叫风角峡谷的地方。因为谷中发生过一场战斗，它直到最近才被人发现。据我的线人说，如今那里到处都是恐怖图腾。$B$B不管那里潜伏着什么邪恶，我都想雇你跑一趟，把可能还留在里面的遗物带些回来。办得漂亮，报酬自然少不了！') ON DUPLICATE KEY UPDATE `Details_loc4` = VALUES(`Details_loc4`);
INSERT INTO `locales_quest` (`entry`, `Details_loc4`) VALUES (41977, '我大半辈子都和风角部族生活在一起，渐渐敬重并珍视他们的传统。如今恐怖图腾在风角峡谷大肆劫掠，我担心风角的历史与文化会就此湮没无闻。$B$B突袭发生时我逃离风角峡谷，脑子里只想着活命。现在我后悔没能把城中那些珍贵的遗物带出来。它们迟早会被全数毁掉，或者被时间遗忘。$B$B我请求你鼓起勇气进入风角峡谷。把你在里面能找到的古物都带回来给我，你会得到报酬。') ON DUPLICATE KEY UPDATE `Details_loc4` = VALUES(`Details_loc4`);
INSERT INTO `locales_quest` (`entry`, `Details_loc4`) VALUES (41983, '你好啊，冻得直哆嗦的陌生人！冒险还顺利吗？在卡纳克努恩住得惯吗？我们能拿出来的东西不多，但只要有一点，都会用最真诚的好客之心与你分享。你有没有兴趣听听故事？我们海象人有许多传说和民间故事可以讲。也许你是来卡纳克努恩练钓鱼的？那就让我给你讲讲月亮鱼 Iqa’quluk 的故事吧！$B$B很久很久以前，我的肚子还没这么圆的时候，那位长者出海钓鱼，在北海里遇到了一条神秘的鱼。那天夜里月光明净，他坐在钓船上，忽然有东西从海底泛起光来！一条巨大的鱼，扁平如浮冰，披着美丽的白色鳞片。月光在鳞上粼粼闪耀。它来得快，去得也快，只留下那个发愣的人。$B$B这故事是不是很精彩？') ON DUPLICATE KEY UPDATE `Details_loc4` = VALUES(`Details_loc4`);
INSERT INTO `locales_quest` (`entry`, `Details_loc4`) VALUES (41984, '在家乡的时候，有人说过我懒。这边喊我“废物！”，那边说“没见过这么不干活的！”——要我说，这些指责可够重的。对此我的回答是：他们说得全对。我能成为钓鱼大师，靠的不是运气，也不是什么藏着不露的天赋。都不是，我就是太闲了，没别的事可干。所以我就钓鱼。钓了又钓。喝了又喝。再钓再喝，直到三十年过去，你就站在我面前了。可你知道吗？我觉得偶尔也该放个小假，你说呢？不过那就得准备些补给——而看来幸运女神站在我这边，你正好来了！$B$B这样吧：给我弄一根备用鱼竿、一个新钓具包，再弄点酒供我这趟小旅途中喝，我就把我老爹留给我的一本书送你，愿圣光照拂他。酒我可不要随便什么，只要你能找到的最好的暗月特殊储备。听明白了吗？') ON DUPLICATE KEY UPDATE `Details_loc4` = VALUES(`Details_loc4`);
INSERT INTO `locales_quest` (`entry`, `Details_loc4`) VALUES (41989, '我一路追查一件古代元素圣物——海神之水神像的踪迹，一直追到这片废墟，却发现这里已经被纳迦占满了。这些滑腻的家伙向来没什么善心，说不定他们来这儿的目的和我们一样。我的战斗本领有限，也没我希望的那么强，所以你能来我真的很感激。我相信凭你的实力，正好能赶在纳迦把圣物带回水里之前把它夺下来。据我所知，它应该就在这废墟过去不远处的洞穴里。祝你好运，需要我的话我就在这儿。') ON DUPLICATE KEY UPDATE `Details_loc4` = VALUES(`Details_loc4`);
INSERT INTO `locales_quest` (`entry`, `Details_loc4`) VALUES (41990, '我发誓他肯定是故意的！那个油腔滑调的小个子人类，不过是个不懂真正荣誉的毛头小子。我在外面面对这些……这些可怕的幽灵，他却待在德莱尼村子里“收集情报”。得了吧！他做的唯一一件事就是拿人家给的食物把自己塞饱。不过我会让他看看，或者说我们会让他看看，我们完全能搞定这事……大概吧。$B$B我和同伴们来到这片海岸有许多原因，其中之一就是寻找新的财宝和黄金来源。莫洛加的人告诉我们，这片废墟里到处是遗物和值钱的东西。我们的钱总是不够用，所以这对我们来说是个不错的进项。你愿意帮我吗？') ON DUPLICATE KEY UPDATE `Details_loc4` = VALUES(`Details_loc4`);
INSERT INTO `locales_quest` (`entry`, `Details_loc4`) VALUES (41992, '当我们的族人被逼离开那片养育我们、承载着我们最美好记忆的故土时，我们失去了许多东西。我自己的双眼就是在那场烈焰的轰鸣中失去的；当时我愚不可及，自以为强大得绝不会在那天死去。而从各方面来说，我确实没错。唉，但失去的比我的双眼更要紧的东西还多着呢——尤其是其中一件，我必须把它找回来。$B$B月蹄部族是个骄傲的民族。自从我们得到众位天界同胞的温暖庇佑，骄傲便在我们心中扎根。我们一向心怀感激、恪尽侍奉，而他们也慷慨赐予我们恩典与礼物。于是……$B$B我们保存了三卷卷轴，每一卷都是向其中一位同胞献上的祷文。逃亡途中，我们设法找回了其中两卷。第三卷呢？遗失了。似乎没人愿意去把它取回，因为没人敢招来长者之怒。可你不是我们村子的人，所以你是让我重见这卷卷轴唯一的希望。$B$B循着指引的脚步走向河角村，穿过那片曾经的家园废墟，找出还残存下来的东西。你会找到的。') ON DUPLICATE KEY UPDATE `Details_loc4` = VALUES(`Details_loc4`);
INSERT INTO `locales_quest` (`entry`, `Details_loc4`) VALUES (41993, '一场试炼摆在我面前，可我不禁要问：要面对它的究竟是我，还是整个部族？我眼神空洞地伸向繁星点点的夜空，却看见月亮正把脸从我的声音旁转开。陡峭的峡谷横在我面前，我不得不在它的边缘小心翼翼地挪动蹄子。害怕坠落，可我必须继续前行。否则，我就无法把这份责任担到最后。$B$B我眯起眼睛，却再也找不到安瑟的光芒。他的光被云层遮住了，我不断问自己，是因为我畏缩不前，还是候选者影奔以某种方式把他从我身边夺走了？$B$B他们盘踞在安瑟之息。污秽的吟唱和黑暗仪式的诡异气息刺痛着我的灵魂。他们一定企图把我们的祖先从安息中扭曲，好为他们对权力与仇恨的贪欲效力。我们都在为河角村的失落哀悼，但他们做出了错误的选择。向北去吧。走上我族人的道路，也走出你自己的路。尽管这让我心痛，但他们都必须被除掉。你愿意做安瑟伸张正义的利刃吗？') ON DUPLICATE KEY UPDATE `Details_loc4` = VALUES(`Details_loc4`);
INSERT INTO `locales_quest` (`entry`, `Details_loc4`) VALUES (41994, '在Shadewalkers之中，有一个人信念坚定，却迷失了自己的道路，还伤透了无数人的心。也许那只是因为她自己的心早已破碎。唉，但动机不能为行为开脱，而她所做的事令人发指。她打算为了微不足道的复仇，把其余的先祖都搅得不得安宁。$B$B她不明白，该去讨回公道的并不是我们。向Mu’sha和An’she祈祷吧，伤害我们的人自会被他们——我们的守护者——所伤。我们不可亲手去求血债血偿。自然自有其道，一切生灵终将付出代价。$B$B我不确定你是否明白我的意思，但你其实不必明白。如果你想向我证明你的用处，就前往安瑟之息，终结她的疯狂。') ON DUPLICATE KEY UPDATE `Details_loc4` = VALUES(`Details_loc4`);
INSERT INTO `locales_quest` (`entry`, `Details_loc4`) VALUES (41995, '你倒是站得笔直，$N，哪怕你的所作所为活像个没脑子的怪物。我问你，你可曾想过质疑我父亲派给你的那些任务？我想没有。毕竟你不过是个为了一己私利而来的嗜血杂种。你的双手沾满了我族人的鲜血。$B$B那个还自称酋长的懦夫可曾告诉过你，他派你去杀的是谁？他有过悔意吗，哪怕一丝一毫？没有，我猜没有。那就让我来告诉你吧。我那愚蠢的父亲选错了目标。他没有让你去杀死那些把河角村付之一炬的Fallen Ones，反而让你杀了他最老的朋友。$B$B滚出我的视线，部落的一员。除非用真正凶手的血来偿还这桩罪孽，否则别再回来。向西南方去，找到河角村的废墟，杀了那个叫Baxdi’zha的家伙。他还在那片饱受折磨的土地上爬行。') ON DUPLICATE KEY UPDATE `Details_loc4` = VALUES(`Details_loc4`);
INSERT INTO `locales_quest` (`entry`, `Details_loc4`) VALUES (41996, '村里那些勾心斗角的事，本来就已经让我这个普通渔夫不得安宁，现在倒好，我连一觉都睡不踏实了。我不知道是什么把这些滑溜溜的恶心家伙从深水里引了上来，但它们可真是爱闹出动静。$B$B离这儿不远处有一座被毁的暗夜精灵聚落。你从岸边应该就能看到。它以前叫奈迪斯，我猜我们现在还是这么叫它——只不过后面要加上“废墟”两个字？算了，想这些也没用。$B$B它们海妖的歌声让我心神不宁。每当Mu’sha在夜空中最亮的时候，它们就会唱歌。那是一首哀伤的曲子，就像唱给疏远已久的父母听。我心里虽然也有几分同情，但还是让它停下来吧。我不在乎你是割掉它们的舌头还是脑袋。办成了，我就给你报酬。') ON DUPLICATE KEY UPDATE `Details_loc4` = VALUES(`Details_loc4`);
INSERT INTO `locales_quest` (`entry`, `Details_loc4`) VALUES (41999, '部族里大多数人还是愿意穿我们打猎换来的兽皮，无论是做口粮还是做日用杂物都离不开它，但也有人偏爱些更精致的东西。我们家世代都做一种材料，甚至以它为姓。而正因为缺了那种只能从蛾子身上取来的丝，你我才会有现在这番对话。$B$B在莫洛加村以南，你会找到月绸谷。那片被月绸蛾视为家园的地方，笼罩着一种奇异的美。正巧，交配季节刚过，新生的幼虫现在应该已经结茧了。替我小心地收集一些虫茧；我会好好饲养这些幼蛾，从此为部族收取它们的丝。') ON DUPLICATE KEY UPDATE `Details_loc4` = VALUES(`Details_loc4`);
INSERT INTO `locales_quest` (`entry`, `Details_loc4`) VALUES (42002, '你手中那团带刺的触须不停扭动，以一种无法解释的方式向外伸展。它越缠越紧，一圈圈裹住你的手。你被这景象迷住了，竟没察觉那团东西上长着一只眼睛——以及一根倒刺，它当即刺进你的掌心。剧痛之下你想把寄生物扯下来，它却更深地钻进你的血肉。转眼间，它与你合为一体。你又惊又怕，粗重地喘着气，听见脑子里有个声音。起初很微弱，你四下张望想找出声音的来源，却找不到。你惊恐地看向被感染的那只手——迎面而来的是一道灼热的注视，还有你刚才听见的那个声音：$B$B“容器，你的身上已被赋予使命。就像虫子听命于它的女王，你也将成为我的工具。到希利苏斯荒凉的沙丘中去，进入废墟之城安其拉。在那里你会找到一把剑。把它据为己有。”') ON DUPLICATE KEY UPDATE `Details_loc4` = VALUES(`Details_loc4`);
INSERT INTO `locales_quest` (`entry`, `Details_loc4`) VALUES (42003, '你苦苦搜寻来的东西，却平常得让人意外。没有分量，只是一块说不出材质的金属板，握在手里轻飘飘的。你想不通那寄生物究竟看上了这剑的什么，而它仿佛能读你的心思，又开口点醒你。$B$B“此刃已沉睡万古，等着苏醒的一天。它生于你那个世界的混沌，渴望重获自由。去观察。去学习。去理解。我的仆从，我感到你体内涌动着对力量的渴望。来，成为成就此刃天命的一环，我便允许你尝到它力量的一丝滋味。$B$B去寻找在你那幼稚世界上游荡的恶魔身上的符文。再取一根恐惧魔王的指甲，用它把此刃的用途刻进剑身。两样东西都能在诅咒之地的腐化之痕找到。要做到这一点，就到你们称为艾萨拉的这片土地上，到 Arkkoran 神殿东南方的深海海渊里寻找深渊祭坛。”') ON DUPLICATE KEY UPDATE `Details_loc4` = VALUES(`Details_loc4`);
INSERT INTO `locales_quest` (`entry`, `Details_loc4`) VALUES (42005, '寂静充盈着你的脑海。有那么一瞬，你以为一切都已经结束，可手中那团搏动的东西却提醒你现实依旧。而就在这个念头刚刚掠过脑际之际，那声音便仿佛回应着你内心的声音般响起。$B$B“虚假的希望，配不上你这样前途无量的仆从。更伟大的力量可不会乐于见到你抱住自己头脑编造出的幻象不放。不，真理只有一个。一个绝对的真理，一个圆满的真理。Thil’phoral正因你的顺从而力量充盈。它的道路上还差最后一步。必须在剑与裂隙之间牵起一道联结，好让Thil’phoral得以观察、理解、宣告。$B$B进入那片被你族人称作翡翠梦境的梦境。在那里，去见索尔纽斯——更伟大的力量的一次失败实验。终结他的存在，从他的遗物中取走那块碎片。最后一步，我的仆从。”') ON DUPLICATE KEY UPDATE `Details_loc4` = VALUES(`Details_loc4`);
INSERT INTO `locales_quest` (`entry`, `Details_loc4`) VALUES (42007, '矮人尸体的手里死死攥着一块金属碎片，表面光洁如新，上面刻着你完全看不懂的文字。看样子他为此丢了性命。你把它收下，打算把这件事、以及他朋友的死讯告诉 Caskbelly。') ON DUPLICATE KEY UPDATE `Details_loc4` = VALUES(`Details_loc4`);
INSERT INTO `locales_quest` (`entry`, `Details_loc4`) VALUES (42008, 'Ba’la dash, malanore。我听说，卡兹莫丹的深处洞穴里栖息着一种特别的雪豹，它们的毛皮泛着不同寻常的白色光泽。我的主人阿斯塔洛·逐日者为他即将到来的晚宴订做了一件独一无二的披风，我打算把那种白毛和我手头最上等的织锦布匹结合在一起。$B$B冒险者，你对这桩赚钱的买卖感兴趣吗？如果你能从霜鬃谷里给我带回一张完美无瑕的雪豹皮，我就从我的收藏里挑一件好东西作为报酬。成交吗？') ON DUPLICATE KEY UPDATE `Details_loc4` = VALUES(`Details_loc4`);
INSERT INTO `locales_quest` (`entry`, `Details_loc4`) VALUES (42009, '也许你自己已经感受过它，或者已经遭遇过它的某种显现，但卡利姆多的森林中正有一场侵染疯狂蔓延。它感染花草与生灵，使它们陷入疯狂，不分敌友地发起攻击。阴险的低语在自然之灵间悄然流传，号召平衡的守护者们对抗这场腐化。$B$B其中之一便是高贵纯洁的Loktanag，成长与适应的活化身。他们感应到海加尔山深处的异动，就在木喉要塞神圣的殿堂之下。Loktanag深入这熊怪的神圣家园，试图阻止瘴气的扩散，但他们的力量显然不够。如今众灵为他们腐烂的躯体哀悼，那躯体渗出有毒的淤泥，弥漫的正是他们想要阻止的腐化。$B$B$N，我请求你让Loktanag安息。像他们这样高贵的生灵理应重回轮回。平衡必须恢复。') ON DUPLICATE KEY UPDATE `Details_loc4` = VALUES(`Details_loc4`);
INSERT INTO `locales_quest` (`entry`, `Details_loc4`) VALUES (42010, 'Ishnu’daldieb，陌生人。在Maras’ethil居然还能见到活人大摇大摆地走动，真是稀奇。还是说我的脑子在跟我开玩笑？失礼了，长年的与世隔绝让我连礼貌都生疏了。你可以称我为Keeper N’las，眼下这样称呼就足够了。说起来，今天遇上你，也许正好能解开我苦苦寻觅的难题。你看，这里并不是我主要的居所。虽然这里的景色美得令人屏息，但我那些可怕的邻居实在粗鲁得让我受不了，所以我才住在西北方更远处的这片海岸群山中。遗憾的是，我往返那边的唯一手段突然失灵了，着实让我吃了一惊。我能修好它，可这一趟路实在太折腾，而且看你的装束，你比我更适合干这活儿。$B$B沿着山脉往上走，在冬泉谷的冰原上，你会找到枭翼树丛。积雪深处埋着一些被封冻在时光中的瓶子。给我带一小把回来。') ON DUPLICATE KEY UPDATE `Details_loc4` = VALUES(`Details_loc4`);
INSERT INTO `locales_quest` (`entry`, `Details_loc4`) VALUES (42011, '海岸北边，紧挨着月蹄居所、与安瑟之息并排的地方，有一座火山口。那里闪烁着耀眼的巨光，坑底有一块巨大的水晶，还能看见其他较小的晶簇。看来蓝龙既在守护它，也在收集它。$B$B这些巨龙和龙类对你一个人来说恐怕太强了。不过要是你够机灵，也许能对付那些幼龙，尽管它们通常也是一群群地蜷在一起。这活儿我建议你找另一位冒险者帮忙。$B$B啊，对了。我讲着讲着都忘了说正事了，是吧？我敢肯定，这些龙手里会有被魔法灌注过的德拉诺水晶。虽说我对奥术一窍不通，但我的眼睛还是能分辨出未经加工、毫无力量的那种和灌注过力量的那种。话虽如此，需要的数量是一块。') ON DUPLICATE KEY UPDATE `Details_loc4` = VALUES(`Details_loc4`);
INSERT INTO `locales_quest` (`entry`, `Details_loc4`) VALUES (42012, '连这块水晶都超出了我的认知。令人沮丧，又无比幸福。我明白了自己其实一无所知——而这恰恰正是我一直做下去的原因。也许我这话没什么道理。但对我这样的人来说，研究闻所未闻的物品与知识，本身就带来某种喜悦。$B$B你在外面冒险，我在自己的头脑里冒险：设想着不可能的事，看看它是不是真的不可能。听我这么叨叨，像个要第一次骑马的孩子。$B$B不说这些了。我要你把这个挎包带到南边的莫洛加村，到了你自然会知道。他虽然之前不肯跟我谈水晶的事，但我相信这件礼物也许能让他松口。去找 Heghala，那位德莱尼水晶建筑师，告诉他我也在赶来的路上，要谈谈我的研究结出了什么果实。') ON DUPLICATE KEY UPDATE `Details_loc4` = VALUES(`Details_loc4`);
INSERT INTO `locales_quest` (`entry`, `Details_loc4`) VALUES (42013, '我们长途跋涉，来向月蹄部族寻求庇护。我们一向以亲人相称，可我却受到了冷遇。长者给我的接见倒像是打发一个乞丐，而不是接待一位老朋友。我很不快，但我没有立场争辩。$B$B他要的是酬劳，是人情。他要求我和我的族人们去攻打月之林地，杀掉那里的德鲁伊。他声称他们因为信奉Lo’sho而变得冷漠、古怪、狂热过头。可他的言谈和举止恰恰证明，他才是那个狂热的人。我从没听谁把安瑟挂在嘴边这么多次。$B$B他的要求简直荒谬。我们从千针石林走了好几天才到这里，根本不可能去对付一整片德鲁伊林地。你看起来像个经验丰富的冒险者。你愿意前往月之林地——从这里往南，越过河角村废墟，在旋风神殿后面——杀掉那些德鲁伊，给我族一个休养生息、得以存活的机会吗？') ON DUPLICATE KEY UPDATE `Details_loc4` = VALUES(`Details_loc4`);
INSERT INTO `locales_quest` (`entry`, `Details_loc4`) VALUES (42014, '看来Windhorn派了个代表来，而不是亲自听我差遣。聪明，这并非我所期望或想要的，不过安瑟暂时认可他们配得上。既然你已经接下了他们的角色，想要成为他们存续的支柱，那我就交给你下一个任务。$B$B一个邪恶的污秽使者潜入了月之林地的土丘巢穴。正是奉他主人之命，他和那些可悲的爪牙才部分唤醒了沉睡在那里的德鲁伊。如今他们被困在清醒的梦境之中，被束缚于Lo’sho和他带来的混乱。$B$B别搞错了，这邪恶虽属恶魔之流，却听命于最年幼的天界同胞。由此可见，这最小的兄弟对长兄Mu’sha何等怨恨、何等狭隘，竟要征服并腐化她的敬拜之地。现在就出发，回到林地，深入那土丘巢穴；你会在那里找到萨特Zandaxxius和他召来的可悲妖精。') ON DUPLICATE KEY UPDATE `Details_loc4` = VALUES(`Details_loc4`);
INSERT INTO `locales_quest` (`entry`, `Details_loc4`) VALUES (42015, '长者不许我踏入月之林地，却派了你——或者更确切地说，派了Windhorn——去“处理”这件事。我很好奇他对你说了什么样的鬼话，说那里的德鲁伊是受了Lo’sho的影响才发了疯。我们长者的心智一天比一天更糟糕。许多人都看在眼里，许多人却视而不见。$B$B我们没有资格质疑他的话。他是我们的酋长，在年轻人忍无可忍之前，我们必须恪守传统、服从命令。但你无须如此。那片林地确实被腐化了，但不是被Lo’sho。那不过是一位过分狂热的酋长的臆想罢了。它被恶魔的力量玷污了。$B$B我另有任务交给你。一位我曾视为朋友的树妖堕入了腐化。Lo’sho允许我在梦中最后见她一面。请你回到林地，让我的朋友Landis Stargazer安息吧。如果我没记错，她应该还在林地间奔跑。') ON DUPLICATE KEY UPDATE `Details_loc4` = VALUES(`Details_loc4`);
INSERT INTO `locales_quest` (`entry`, `Details_loc4`) VALUES (42019, '这片海岸上住着许多生物，其中最特别的要数雷象。它们稀少、近乎游居，宁可独处也不结群。话虽如此，它们既不好找，也不好打。可我老实说，我正在打造一件武器，需要它们一根粗壮的象牙。$B$B我想你明白我要说什么，就不用我再唱那段调子了。这活儿简单，却不容易——第一难是找到它，第二难是打赢它。要是你能给我带回一根象牙，我就把亲手打造的一件武器赏你。$B$B那两件我都不太满意，不过这并不代表它们不可靠。我真正想做的是把长矛，给我弟弟做的。至于上哪儿找雷象，我要能说得出来早说了，你就在冒险路上多留意吧，说不定就碰上了。') ON DUPLICATE KEY UPDATE `Details_loc4` = VALUES(`Details_loc4`);
INSERT INTO `locales_quest` (`entry`, `Details_loc4`) VALUES (42020, '真是一杆好枪。我为此无比自豪。锻造这件武器时，我倾注了全部的爱、汗水与热情。等我弟弟完成训练，他就会带着它上战场。这，这就是我作为兄长的责任：为他提供追求抱负的凭借，说实话，也是实现我自己抱负的凭借。$B$B若锻造这件武器时少了一分爱意，它就不会如此坚固、如此耐用、如此独一无二。我很好奇我弟弟会怎么看它，又会给它取什么名字。当然，我还有一件事想请你帮忙。$B$B你愿意前往血蹄村，到战士的训练场去找哈夫纳·巨石图腾吗？他就是我满怀深情提起的那个弟弟。我想他的训练还没结束，所以你多半能在那里找到他。从莫高雷的雷霆崖往南走就能到村里。请代我向他致以问候。') ON DUPLICATE KEY UPDATE `Details_loc4` = VALUES(`Details_loc4`);
INSERT INTO `locales_quest` (`entry`, `Details_loc4`) VALUES (42023, '许多年来，我们熊怪一直敬奉自然诸神，其中双子神乌索尔与乌索克居于我们信仰的中心。为纪念他们为这个世界做出的牺牲，我们部族最伟大的萨满会穿上一件灵魂之衣——据说能与荒野诸神共鸣的灵力护甲。如今它们失落在木喉的隧道里，不是落在Withermaw手中，就是落入了他们腐化的爪牙手里。$B$B这套仪式头饰能让人与自然之灵的智慧相连，使佩戴者获得启迪，为众人的福祉做出正确的决断。把头饰和一些材料带给我，我会重新打造它，让它助你解放木喉要塞。') ON DUPLICATE KEY UPDATE `Details_loc4` = VALUES(`Details_loc4`);
INSERT INTO `locales_quest` (`entry`, `Details_loc4`) VALUES (42024, '许多年来，我们熊怪一直敬奉自然诸神，其中双子神乌索尔与乌索克居于我们信仰的中心。为纪念他们为这个世界做出的牺牲，我们部族最伟大的萨满会穿上一件灵魂之衣——据说能与荒野诸神共鸣的灵力护甲。如今它们失落在木喉的隧道里，不是落在Withermaw手中，就是落入了他们腐化的爪牙手里。$B$B这件仪式披风上挂着提灯，厚重的帷幔垂在祭司的肩头。借此，他们象征性地背负着先祖的重担，以及未来的种种变数。把披风和一些材料带给我，我会重新打造它，让它助你解放木喉要塞。') ON DUPLICATE KEY UPDATE `Details_loc4` = VALUES(`Details_loc4`);
INSERT INTO `locales_quest` (`entry`, `Details_loc4`) VALUES (42025, '许多年来，我们熊怪一直敬奉自然诸神，其中以双子神乌索尔与乌索克为中心。为了纪念它们为这个世界作出的牺牲，我们部族最伟大的萨满会穿上一件灵性外衣——据说那副灵甲能与荒野诸神共鸣。如今它失落在木喉的隧道里，不是在 Withermaw 手里，就是被他们那些堕落的爪牙拿着。$B$B那件仪式外衣会像母亲温暖的怀抱一样裹住穿着它的人，正如自然把丰厚的馈赠给予珍惜它、守护它的人。披上它，萨满便能与自然森林间低语的生机融为一体。把外衣和几样材料给我，我会重新把它做成能帮你解放木喉要塞的样子。') ON DUPLICATE KEY UPDATE `Details_loc4` = VALUES(`Details_loc4`);
INSERT INTO `locales_quest` (`entry`, `Details_loc4`) VALUES (42027, '许多年来，我们熊怪一直敬奉自然诸神，其中双子神乌索尔与乌索克居于我们信仰的中心。为纪念他们为这个世界做出的牺牲，我们部族最伟大的萨满会穿上一件灵魂之衣——据说能与荒野诸神共鸣的灵力护甲。如今它们失落在木喉的隧道里，不是落在Withermaw手中，就是落入了他们腐化的爪牙手里。$B$B这套仪式护腿象征着自然青翠的生命力。它灌注了荒野的祝福与恩泽，能让我们的萨满与灵魂合一，聆听它们的召唤。把护腿和一些材料带给我，我会重新打造它，让它助你解放木喉要塞。') ON DUPLICATE KEY UPDATE `Details_loc4` = VALUES(`Details_loc4`);
INSERT INTO `locales_quest` (`entry`, `Details_loc4`) VALUES (42028, '许多年来，我们熊怪一直敬奉自然诸神，其中双子神乌索尔与乌索克居于我们信仰的中心。为纪念他们为这个世界做出的牺牲，我们部族最伟大的萨满会穿上一件灵魂之衣——据说能与荒野诸神共鸣的灵力护甲。如今它们失落在木喉的隧道里，不是落在Withermaw手中，就是落入了他们腐化的爪牙手里。$B$B这双仪式长靴让穿戴者踏稳于我们的世界，为萨满作为自然使者的使命增添谦卑与质朴。带一双靴子和一些材料给我，我会重新打造它，让它助你解放木喉要塞。') ON DUPLICATE KEY UPDATE `Details_loc4` = VALUES(`Details_loc4`);
INSERT INTO `locales_quest` (`entry`, `Details_loc4`) VALUES (42030, '不久之前，其实就在几天前，一只古怪的箱子被送到了我庄园的门前。那箱子就那么一夜之间出现，上面只附着一个散发着香气的奇怪信封。显然，谜团并未就此结束，只是此事我留待日后再谈。至于箱子本身，它的表面刻着一弯新月，周围环绕着许多繁复的纹饰。对我们拉文霍德的人来说，这只意味着一件事：里面的东西必定价值连城。$B$B我们自然着手调查，并向暴风城与幽暗城里的线人传去消息，他们随即开始打探这只神秘箱子的下落。不幸的是，他们查到的东西让他们……中止了合作。我要你把他们的发现弄到手，要么从他们口袋里偷出来，要么逼他们吐出来。我确信他们身边就带着什么见不得光的东西。他们名叫Lord Finwald和Ebenezer Dregheap。') ON DUPLICATE KEY UPDATE `Details_loc4` = VALUES(`Details_loc4`);
INSERT INTO `locales_quest` (`entry`, `Details_loc4`) VALUES (42031, '看来我们手上的是一件大分裂之前的圣物匣，那是万年前暗夜精灵与他们上层精灵精英冲突之后那场毁灭性灾难留下的东西。$B$B我跟你提过箱子上附着一个信封，你还记得吗？里面是一封信，工整地写在淡紫色的纸上，纸面还带着野花的芬芳。信上潦草地记述着关于这只箱子的零碎信息，比如说它没有任何常规的锁，却始终紧闭。从这里的记载来看，那把锁是可以重现的，然而……我们只有一份工具和材料的清单，却没有重铸锁具的图纸。说实话，真让人失望，但我们只能尽力打好手里这副牌。你的下一步是登上黑翼之巢，从奈法利安的私人首席炼金师那里弄到一份转化合金，再从他手下的地精爪牙那里弄到源质矿石。') ON DUPLICATE KEY UPDATE `Details_loc4` = VALUES(`Details_loc4`);
INSERT INTO `locales_quest` (`entry`, `Details_loc4`) VALUES (42034, '万事俱备。图纸已经完成，合金与矿石也已到手，接下来就是把它们合成完整的锁。所幸我有位老相识，或许正是请教此事的不二人选，尽管他与我组织的关系已不复当年。不过，一点金币就能解决的问题都不算问题。$B$BArgur Rustbrand就是我们要找的那位出类拔萃的铁匠。据我所知，他醒着的每一刻都耗在黑石深渊的Mold Foundry里。来，收下这只箱子，里面装着我们目前搜集到的一切，还有些金币用来支付他的工钱。$B$B还有一件事，$N。这位脾气火爆的矮人如今只肯和黑铁矮人说话。我建议你给自己弄一身像样的伪装，否则这桩买卖谈不成。') ON DUPLICATE KEY UPDATE `Details_loc4` = VALUES(`Details_loc4`);
INSERT INTO `locales_quest` (`entry`, `Details_loc4`) VALUES (42039, '我的斥候已经确认了西南方一处洞穴的位置。那里叫霜鬃谷，可以说是丹莫罗所有巨魔事实上的首府。如果我们想彻底终结这个威胁，就必须从最深处把它连根拔起。传闻他们的首领是一个叫Battlemaster Ubukaz的家伙，一位备受敬畏的霜鬃战士，如今正召集他的战士投入战斗。我要你找到他，为铁炉堡讨回公道。$B$B我建议你带上援军，那洞穴里有多少敌人可就说不准了。') ON DUPLICATE KEY UPDATE `Details_loc4` = VALUES(`Details_loc4`);
INSERT INTO `locales_quest` (`entry`, `Details_loc4`) VALUES (42040, '<Ranix松了一口气，汗水顺着额头淌下来。>$B$B天哪，你总算想通了，我真是太高兴了。这里动武没有意义，其实，我有活给你干！对——对，你看，我们这儿没卖武器，也没卖那种东西。我只是个诚实的商人，想从这些霜鬃手里弄到点东西。$B$B既然你在这儿东翻西找、伸张正义或者随便什么，我觉得咱们合作对双方都有好处。事情是这样的，霜鬃手里有块我想要的稀有石板，可他们迟迟不肯交出来。那东西叫Kazgan石板，就在这些走廊的某个地方……$B$B<Ranix清了清嗓子。>$B$B怎么样？干活换金币？') ON DUPLICATE KEY UPDATE `Details_loc4` = VALUES(`Details_loc4`);
INSERT INTO `locales_quest` (`entry`, `Details_loc4`) VALUES (42041, '听好了，伙计。我真不想承认，可我们这回是陷进泥里了。Kurzen 营地那帮疯子觉得抢了山上的联盟营地还不够，又跑来照顾我们了。跟鳄鱼、老虎、黑豹、迅猛龙和巨魔周旋已经够糟了——不，这帮疯子现在也压到我们头上。还好我们轻松打退了他们，可他们顺走了不少补给和装备。$B$B你看着像个脑子清楚的。我给你做个交易：帮兄弟们给营地弄点补给，我就把野外生存那些真家伙的门道教给你。怎么样？') ON DUPLICATE KEY UPDATE `Details_loc4` = VALUES(`Details_loc4`);
INSERT INTO `locales_quest` (`entry`, `Details_loc4`) VALUES (42046, '旅行者，希望你在我的家里感到宾至如归。这段时间你可以随意使用它，因为我很快就要动身前往月蹄居所了。一场祭拜仪式即将开始，我和许多人一样，想前去参加。$B$B按传统——至少是我个人的传统——要带上一捧四处游荡的鹿翼鸟的羽毛，作为献给Mu’sha母亲的供品。这简单却有力地提醒着我们：在这美丽而严酷的环境中，我们有能力自立。$B$B既然你曾是我的客人，而我也日渐老去，我想请你回报我的好意，带七根鹿翼鸟羽毛给我。你会在我家周围的田野上看到不少鹿翼鸟。带着勇气和敬意去面对它们；别把这当作一次无谓的杀戮，而要把它当作证明——证明你有能力保护自己，保护你有亏欠的人。') ON DUPLICATE KEY UPDATE `Details_loc4` = VALUES(`Details_loc4`);
INSERT INTO `locales_quest` (`entry`, `Details_loc4`) VALUES (42047, '最近我从安瑟之息那里感受到了一股阴郁的能量。它似乎没有影响到那里的亡者，却无疑波及了先祖广场。$B$B好几位先祖被从生死帷幕之外的沉睡中惊醒，爬起来宣泄他们的不满。好在就像被宠坏的孩子一样，要让这些亡者记起自己早已不属于这里，并不需要费多少功夫。$B$B所以，要是你愿意的话，就当是为了让我这个老太婆能得个安宁，去把他们教训几下吧。不过要当心，他们在躁动中听不进道理，也分不清敌友。是坟墓中的愤懑让他们变得好斗。同样地，别怕杀死他们——他们本来就死了。') ON DUPLICATE KEY UPDATE `Details_loc4` = VALUES(`Details_loc4`);
INSERT INTO `locales_quest` (`entry`, `Details_loc4`) VALUES (42049, '看来我摆弄的东西，连我自己都无法想象其力量。怎么，你不太懂幽默？唉，我没法净化这些珠子。很明显，不管是什么东西在影响熊怪，它都确保了一点：这腐化不是随便什么人都能驱散的。光是应付这些死物我就如此吃力，更别提去安抚那些已经被腐化的熊怪的心智了。$B$B不过，眼下这还不是我们最该操心的事。既然我无法净化这些珠子，只能请你前往艾萨拉，寻找能替我们办到这件事的人。你必须找到海达希亚的领主们，尤其是海达克西斯公爵。我希望他愿意帮助我们安抚月语海岸的元素同胞。元素之间有时也会有分歧，但我斗胆希望他会听进去并伸出援手。海达克西斯公爵就在艾萨拉东南海岸外的一座孤岛上。') ON DUPLICATE KEY UPDATE `Details_loc4` = VALUES(`Details_loc4`);
INSERT INTO `locales_quest` (`entry`, `Details_loc4`) VALUES (42050, '大地之环是海达希亚水元素珍视的凡人朋友。把那串珠子放到我的一只束缚护腕下面，剩下的交给我的流水来完成。我和你的巨魔朋友一样担忧；珠子里的腐化确实很强。别担心，它还没强到能让像我这样的元素公爵屈膝，不过它显然把熊怪们害惨了。$B$B至于我同胞的神殿，我在月语海岸也感受到了不止一场纷争。他们的守卫已经起身护卫自己的祭祀之地，但也许现在是属于凡人而非元素的时刻。我开始觉得，终有一天我或许必须依靠你们这样的种族，甚至是你。既然这个世界的凡人子嗣想在逆境中挺直腰板，我又怎能拒绝把这份职责交给你呢？取回你的珠子吧，凡人，回到你的巨魔朋友身边，平息我同胞的不安，并坚定你自己的选择。') ON DUPLICATE KEY UPDATE `Details_loc4` = VALUES(`Details_loc4`);
INSERT INTO `locales_quest` (`entry`, `Details_loc4`) VALUES (42051, '元素仍未平息。既然公爵已经把珠串净化，我们就能安抚它们了。月语海湾有三座元素神龛。一座在这南边、月之林地之前，另两座沿路往北到安瑟之息就能找到。每座神龛里都立着一块萨满石，就跟我身后这块一样。$B$B这块石头是元素位面与我们这个位面之间的通道，会给他们强大的力量，所以小心别同时面对太多。我要你逐个走访这些神龛，直面那里的元素石。站在元素石旁，把那串珠子高高举起，让它自行发挥作用。我和 Uz’tuk 灌进珠子里的能量与咒语应该足够完成这件事。') ON DUPLICATE KEY UPDATE `Details_loc4` = VALUES(`Details_loc4`);
INSERT INTO `locales_quest` (`entry`, `Details_loc4`) VALUES (42052, '你眼里有一团火焰，在四周的黑暗中烧得正旺。那火焰本身就能说明问题。你不是新手。直说吧，你这个冒险者、这个世界的探索者，很快就将迎来巅峰。嗯，对，你正合适。$B$B我感到你体内有一种饥渴，那种饥渴让我们亲如兄弟。你也渴求危险与痛苦的狂喜。我，碎鳞战团的 Gor’dush Jawtaker，向你提出一场力量与意志的试炼。前方，在那道水晶光柱照着的环形山里，你会找到几条幼龙和蓝龙军团的低阶爪牙。在它们的血里洗个澡，然后回来见我。$B$B要完成这件事，你得有自己的战团。拉上你看得顺眼的任何同伴——任何流落在这片海岸的友人、冒险者。带他们一起，投入猎龙这项永恒的荣耀中去。把这桩勇气的传奇完成，我就把更辉煌的命运交到你手上。') ON DUPLICATE KEY UPDATE `Details_loc4` = VALUES(`Details_loc4`);
INSERT INTO `locales_quest` (`entry`, `Details_loc4`) VALUES (42053, '我之前提过一条荣耀之路。在德拉诺，当我的族人被嗜血和收集头骨的贪欲侵蚀时，我们把通往这个世界的道路称作荣耀之路。那时的我们真是误入歧途的蠢货。$B$B那条路是用白骨铺成的——无辜者的白骨，或是被我们扭曲的目的视作敌人的白骨。不会再有下次了。那上面根本找不到什么荣耀。我做过许多让我无法自豪的事，无论是出于自己的意愿，还是听命于他人。我再说一次，不会再有下次了。$B$B去追寻另一种荣耀吧——阻止那些本应守护凡人、如今却认为凡人不配被守护的家伙。找到召星者和Spellstriker这两头幼龙。一头守着一块水晶，另一头盘踞在北边岛上的Vynagosa’s Rest。把它们的颚带来给我，我会以此为凭赐你一份奖励。') ON DUPLICATE KEY UPDATE `Details_loc4` = VALUES(`Details_loc4`);
INSERT INTO `locales_quest` (`entry`, `Details_loc4`) VALUES (42054, '刚才有个信使在找你，$N。我想她是牧师训练师 Nuhlok 派来的。如果这张便笺是 Nuhlok 写的，我劝你赶紧读一读。') ON DUPLICATE KEY UPDATE `Details_loc4` = VALUES(`Details_loc4`);
INSERT INTO `locales_quest` (`entry`, `Details_loc4`) VALUES (42055, '我已经把能教你的都教给你了，也就是说，你已经超出了我的期望。等你准备好离开红云台地时，去血蹄村找我的兄长Pargan Starstrider。他会教你更多我们信仰的教义与历史。不过作为你的第一位老师，我也必须把我在修行中积累的心得分享给你。$B$B天体兄妹，朋友，他们真的就是兄妹。虽然Lo’sho由Mu’sha所生，但她待他更像弟弟而非儿子。就像任何家庭一样，他们也会争吵。Lo’sho降生时，一副沉重的担子便压在了他身上。Mu’sha和An’she也不例外，因为大地母亲睁开双眼，他们便在那里了。我承认自己有偏心——我最崇敬Lo’sho。他诞生于Mu’sha目睹燃烧军团之下的世界时承受的痛苦，他带来希望。他会与你同哭同笑。他不作评判，只是倾听与给予。出发前请记住这一点。') ON DUPLICATE KEY UPDATE `Details_loc4` = VALUES(`Details_loc4`);
INSERT INTO `locales_quest` (`entry`, `Details_loc4`) VALUES (42056, '来，让我们试试你学到的东西。从这里往南，穿过战士们训练的图腾环，在树影与枝叶下，你会找到 Brave Greenhorn。他受了伤，身形高大，却还守着被风险投资公司霸占的冰蹄水井。$B$B他接到的命令只是观察，可他没弄明白，反而做了相反的事——跟风险投资公司动了手，好不容易才捡回一条命。你的任务是找到他、治好他，用韧强化他的意志，让他想起自己还有可以依靠的同伴，好让他回到村里召集人手，面对眼前的敌人。$B$B办成这件事，等你回来我们就谈谈 Mu’sha。') ON DUPLICATE KEY UPDATE `Details_loc4` = VALUES(`Details_loc4`);
INSERT INTO `locales_quest` (`entry`, `Details_loc4`) VALUES (42061, '啊。一个冒险者。$B$B<阿斯塔洛的嘴角微微一撇。>$B$B真走运……我正好需要一个……可以牺牲的人。$B$B我派我的表弟Andanil去了卡利姆多北部月语海岸的遥远滩岸。我交给他的任务相当重要。可惜，他的能力配不上这份重任。$B$B已经过去好几周了。没有消息，没有报告，也没有任何能让我安心——他尚未把我们家族的名声丢尽——的东西。$B$B<阿斯塔洛把手按在胸口，脸上换出一副苍白做作的关切表情。>$B$B要是他遭遇什么不幸，我会……悲痛欲绝的……$B$B你要前往月语海岸，查明他的状况。要是他奇迹般地还活着，任务也照计划推进，你就观察并回报。要是没有，你就确保它推进。$B$B前往卡利姆多的船从风行者码头出发。别让我久等。') ON DUPLICATE KEY UPDATE `Details_loc4` = VALUES(`Details_loc4`);
INSERT INTO `locales_quest` (`entry`, `Details_loc4`) VALUES (42065, '德莱尼。$B$B来自破碎世界的古怪种族。就是那个世界——我们那位叛徒王子宁可舍弃自己的族人也要投奔的地方。$B$B<Rhys 啐了一口。>$B$B东北边有个村子。他们不与外人来往。我们拿东西换过他们的水晶。怪东西，明明没有风，它们却嗡嗡作响。我不信他们，不过他们还没对我们拔刀。暂时没有。$B$B在沼泽和森林里就不一样了。那些自称堕落者的东西在芦苇丛和林线之间游荡。他们不谈判。毫无预兆地扑上来，把你连皮带肉剥个干净。我见过他们留下的场面。$B$B只要他们还活着，我们在这里什么都建不起来。这些家伙在侧翼游荡，探险队就永远谈不上安全。$B$B去猎杀他们。躲在哪里就杀在哪里。拿四十颗他们的头来作证。对，四十颗。别问为什么是这个数。这片沼泽里到处都是他们，你不用担心凑不齐。$B$B杀到连泥浆都染红为止。') ON DUPLICATE KEY UPDATE `Details_loc4` = VALUES(`Details_loc4`);
INSERT INTO `locales_quest` (`entry`, `Details_loc4`) VALUES (42066, '那些傻瓜以为德莱尼水晶是我们的救星。$B$B<Tesania 笑了，笑声清亮刺耳，像是刚听到一个绝妙的笑话。>$B$B救星。救我们。真是个好笑的想法。我们族人是没救的。不过我打算尽可能拖延那个必然的结局。$B$B<她瞥了一眼旁边的两个凋零者，笑容褪去，换成毫不掩饰的鄙夷。>$B$B我可不想变成那副样子。东边是 Maras’ethil 的废墟。那里曾是上层精灵的一处学术中心，如今成了我们傲慢的破败纪念碑。老样子。我的研究表明那里还留着一些神器。古老。强大。某些人会愿意拿法力水晶大方交换的那种。非常大方。$B$B至少给我带四件值得我花时间的藏品来。我保证，你拿到的报酬会比等着我们其余人的结局愉快得多。') ON DUPLICATE KEY UPDATE `Details_loc4` = VALUES(`Details_loc4`);
INSERT INTO `locales_quest` (`entry`, `Details_loc4`) VALUES (42067, '在那场……事故之前，我们弄到了一批数量可观的德莱尼水晶。它们效力强大，确实，满含可能。可总觉得缺了点什么。我能感觉到。$B$B不久前，北边落下一颗巨大的陨石。撞击时把大地都撕开了，它的到来还引来了许多蓝龙。仅这一点就足够说明问题了。$B$B那块石头浸透了奥术能量。用对地方，对我的研究价值无可估量。我相信它能与德莱尼水晶产生我们尚未见过的共鸣。具体的原理并不重要。$B$B关键在于：我需要一块样本。$B$B守着撞击点的龙充满敌意，我不会要你去送死。不过，堕落者就没有这种顾虑。他们不太看重性命，包括自己的。他们很可能从陨石上捡走了碎片。如果是这样，你会在北边的 Servitor’s Sanctuary 找到它们。去搜一搜，把你能找到的东西带回来。') ON DUPLICATE KEY UPDATE `Details_loc4` = VALUES(`Details_loc4`);
INSERT INTO `locales_quest` (`entry`, `Details_loc4`) VALUES (42069, '我抽不出任何人手。他们是学者、奥法师，是受训用于研究而非屠戮的头脑。我需要他们清醒、专注、持续工作。若我派他们进那个巢穴，我失去的不只是士兵，而是我们仅剩的那点进展。$B$B你不一样。你对我家族没有义务，对我表亲的野心也没有誓言。而你行事的样子，像是真正见过战场的人。这正是我需要的。$B$B仔细听好。我需要你的帮助，而我会给你与这份风险相称的报酬。$B$B去那个巢穴。找出他们发现了什么。找出是什么把他们抽干得如此彻底、如此迅速。它一定还在那里。一件神器。一块石头。无论是什么，它就是源头。$B$B给我带回证据。若有可能，把东西本身带回来。$B$B还有……若有一线可能，哪怕只有一线，别杀他们。除非你不得不动手。若这是魔法所致，那么魔法或许还能逆转它。$B$B<Andanil Sunsworn把目光移向一旁，下颌绷紧。>$B$B我知道这话听起来如何。即便如此。试试吧。') ON DUPLICATE KEY UPDATE `Details_loc4` = VALUES(`Details_loc4`);
INSERT INTO `locales_quest` (`entry`, `Details_loc4`) VALUES (42070, '我想，是时候当面质问我的父亲、质疑他的判断了。但我怀疑他根本不会听；他会一如既往地把它搪塞过去，仿佛他所做的一切都是为了族人的福祉，还有我，他的家人。我需要你替我办一件事。我必须让部落代我出面，而且不能是随便哪个冒险者，得是个举足轻重的人。$B$B我要你南下前往莫高雷的平原，到血蹄村去找贝恩·血蹄。我本可以让你去找他的父亲，但我更愿意请动血蹄家的继承人。同为继承者，他会明白这份重担有多沉。$B$B把我族中你所经历、所目睹的一切告诉他。你将成为我这项任务何等紧迫的见证。只要赢得部落的支持，再借我之名以权威行事，父亲就不得不听。他最恨自己有朝一日得求助于部落，我们正可以利用他的自尊心。别让我失望。这样一来，你也能为自己奉他之命犯下的罪过赎罪。') ON DUPLICATE KEY UPDATE `Details_loc4` = VALUES(`Details_loc4`);
INSERT INTO `locales_quest` (`entry`, `Details_loc4`) VALUES (42071, '老实说，当初听到血蹄与月蹄达成协议的消息时，我父亲就够怀疑的了。月蹄一向看重自己的独立，尤其是他们与暗夜精灵的关系。月蹄一直处在塞纳里奥议会的庇护之下。$B$B月之林地和日之林地的存在就是证明。听说月之林地走了歪路，这实在古怪。照你说的，他们放弃了 Mu’sha 的信仰，改信 Lo’sho，而月蹄长者认为那是一种堕落。$B$B这些事我得好好想想。你会发现我父亲在雷霆崖的长者高地。我想他不会把你赶走——他确实希望月蹄正式加入部落，尤其在如今他们与暗夜精灵闹翻之后。我猜那会把他们推向被迫的孤立，而长者无非是在借部落之力达成这一点。') ON DUPLICATE KEY UPDATE `Details_loc4` = VALUES(`Details_loc4`);
INSERT INTO `locales_quest` (`entry`, `Details_loc4`) VALUES (42075, '你已经找到了写给我的那封信，现在你知道他要向月蹄部族复仇了，那你还想从我这里要什么？有什么是你能问、或者我该说，而你还不知道的？你总不可能要我背叛自己的主人吧。可你正是这个意思，这就是你的目的：让我细细告诉你他打算做什么，他的心智是否还属于他自己，还是说这只是恶魔势力在从中作祟、想要腐化一切。$B$B行，先完成我一件事，我就把话告诉你。如你所知，我的主人已经去了 Tyrandas，可凭你现在的样子，你毫无胜算。尤其是单打独斗。你有盟友吗？有朋友吗？召集他们，一起去 Tyrandas。别往岛中心走，向西去如今已成枯萎营地的那个地方。把那些该死的 grell 杀干净，让那些扭曲的园丁安息。证明你的本事，我就开口。') ON DUPLICATE KEY UPDATE `Details_loc4` = VALUES(`Details_loc4`);
INSERT INTO `locales_quest` (`entry`, `Details_loc4`) VALUES (42076, 'Mothshroud正在吸取他麾下德鲁伊以及所有活物的力量，以成全他的野心。我那些失落的兄弟姐妹都变得扭曲、失常，无论是否出于自愿，他们都留下来侍奉我们从前的大德鲁伊。他曾是我的导师，我对曾经的他仍怀着深深的敬意。我从没想过，我竟然要为两位亲近于心的首席德鲁伊承受哀悼之痛。也许是我太盲目，没能看清，但他让我想起了大德鲁伊范达尔·鹿盔。$B$B然而大德鲁伊范达尔·鹿盔并没有堕落到与萨特结盟、向Blue Child祈求恩惠，只为除掉自己生病的兄长。他已把在他手下效力的所有德鲁伊都推向了没有翡翠梦境的死亡。在你为寻找Mothshroud而一路奋战、击败挡路者的同时，也抽空把他们的护符收回来。那些护符是我们在月之林地安宁的阴影下亲手制作的。把它们带回来给我，好让我埋葬他们。') ON DUPLICATE KEY UPDATE `Details_loc4` = VALUES(`Details_loc4`);
INSERT INTO `locales_quest` (`entry`, `Details_loc4`) VALUES (42077, 'Mothshroud 相信，An’she 才是让 Mu’sha 发光的那一个——借着它的光。所以他要把自己失去的东西也从别人手里夺走，以此惩罚拒绝了替他复仇的月蹄守护神。他的野心是求最小的那位兄妹相助，让白昼的守护神也尝尝失去的滋味，好让他明白哀悼是什么感觉。$B$B他最想问的是：当 An’she 失去最心爱的妹妹时会怎么做？他会不会去寻求与 Mothshroud 一样的复仇，也就是当初被拒绝的那一份？还是到了那时他依旧要故作镇定？唉，这种问题想下去真是没完没了，可你说，它值不值得拿这么多条命去换？我一直盲目跟着 Mothshroud，告诉自己他最终会明白过来。可那个结局不会来了。派你去追他，我心里很难受。他就在艾纳瑞丝神殿顶上，准备把月亮射下来。结束这场闹剧，然后回月蹄村去。') ON DUPLICATE KEY UPDATE `Details_loc4` = VALUES(`Details_loc4`);
INSERT INTO `locales_quest` (`entry`, `Details_loc4`) VALUES (42078, 'Mothshroud 做的事是错的，他为了自己的信念、野心和痛苦，把自己泡在别人的血里。他们难道不像吗？父亲选择了除掉问题，把它抹掉。而这么做，也等于给自己定下了结局。$B$B对于一个以与天界兄妹同行为荣的部族来说，这让我不禁要想：是兄妹的影响让这一切成为可能吗？我们难道只是这场乱局里的棋子——他们争吵的见证者，互相证明谁高谁低的工具？如果这次经历能说明什么，那就是我们不该盲目追随自己的神明。$B$B我们透过大地母亲之眼、透过它的泪所看到的，未必就是我们亲眼所见的东西。要是换作我做父亲的儿子，我会让他去死。可我不这么做，我派你去和他说最后一句话：告诉他事情已经办完，月蹄安全了，他在这里已不再被需要。让他收拾东西，头脑清醒地接受流放。') ON DUPLICATE KEY UPDATE `Details_loc4` = VALUES(`Details_loc4`);
INSERT INTO `locales_quest` (`entry`, `Details_loc4`) VALUES (42080, '父亲跟你提过Ireth Moondancer，对吧？他似乎还活着。如果这封信可信，他当时是被派去奈迪斯废墟取一件东西，却没能按时与Mothshroud会合。既然信还留在那儿，我们大可以断定他根本没到过会合地点。这到底是好事还是坏事，我们早晚会知道。$B$B不知道Mothshroud都说了些什么……向我父亲的恩主复仇？想想也清楚，父亲拒绝了他复仇的请求，他难免怀恨在心。他似乎仍对Lo’sho怀着渴望，但我怀疑那动机并不……纯粹。想太多也没用。去奈迪斯吧，纳迦最爱先玩弄俘虏，说不定Ireth Moondancer还能奇迹般地活着。奈迪斯废墟就在这儿往南。') ON DUPLICATE KEY UPDATE `Details_loc4` = VALUES(`Details_loc4`);
INSERT INTO `locales_quest` (`entry`, `Details_loc4`) VALUES (42086, '奈迪斯。$B$B这么多年过去，这个名字仍留在我脑海里。那是我们族人曾经安静地敬奉森林与月亮的地方。$B$B当伊利丹和他的纳迦来到这片海岸时，奈迪斯是最先陷落的地方之一。镇子在一夜之间烧成灰烬。没有被杀的人逃进荒野……许多人再也没有回来。如今留下的只有废墟。破败的家园。坍塌的高塔。还有散落在尘土里的记忆。这些日子纳迦盘踞在那里，爬行在我们族人曾走过的街道上。$B$B历史不该被留在他们的缠绕之中。$B$B去南边的奈迪斯废墟，搜一搜镇子的残骸，能找回多少遗物就找回多少。信件、护符、旧工具的碎片……任何曾属于那里居民的东西。$B$B给我带三十件这样的遗物回来。') ON DUPLICATE KEY UPDATE `Details_loc4` = VALUES(`Details_loc4`);
INSERT INTO `locales_quest` (`entry`, `Details_loc4`) VALUES (42087, '你把奈迪斯废墟里的那些遗物找回来，干得非常出色。说实话，比我期望的还要好。但附近还有另一个地方，它的故事更让我牵挂。$B$B东边是Tyrandas岛。在更古老的文献中，它被称为静思之地。早在宏伟的神殿在我们的城市中拔地而起之前，伊露恩的祭司们就曾在那里修行。岛屿中央矗立着艾纳瑞丝神殿。以后来时代的标准来看，那不过是一座朴素的圣所，但在当时却备受尊崇。据说在那里研习的祭司们守护着一件圣物，一件曾被月光亲抚过的圣物。$B$B神殿早已被遗弃，是时间和战争造成的。但我们最古老的一些记载坚称，那件圣物从未被移走。如果它仍安放在那片废墟之中，那将是一件具有重大历史价值的遗物……或许在信仰上同样意义非凡。$B$B前往Tyrandas岛上的艾纳瑞丝神殿。搜寻那座圣所，查明那里还残留着何种力量。') ON DUPLICATE KEY UPDATE `Details_loc4` = VALUES(`Details_loc4`);
INSERT INTO `locales_quest` (`entry`, `Details_loc4`) VALUES (42088, '这片土地上的牛头人从来不是我们的敌人。$B$B我们与他们保持距离，他们也与我们保持距离。有时我们甚至还会做交易。这不是友谊，但这是和平，而和平在这个时代已经弥足珍贵了。$B$B所以这件事才让我如此忧心。$B$B一支分裂出去的部族躲进了南边的安瑟之息。他们不再听命于自己的酋长，行为举止也不再是我们熟悉的牛头人。$B$B我的哨兵打着和谈的旗号接近他们。我的两位姐妹再也没能回来。$B$B有什么东西扭曲了他们。是疯狂，是腐化，还是更黑暗的影响，我目前还不得而知。我只知道一件事：任何靠近他们营地的人都会遭到攻击。我绝不会容许这样的威胁留在我们家门口。$B$B前往安瑟之息，在他们造成的暴力蔓延得更远之前将他们铲除。') ON DUPLICATE KEY UPDATE `Details_loc4` = VALUES(`Details_loc4`);
INSERT INTO `locales_quest` (`entry`, `Details_loc4`) VALUES (42090, '你已经证明了纳迦也会流血。现在我们要确保他们再也恢复不了元气。有两名指挥官在统领占据奈迪斯的Tideblade军队。他们是伊利丹的军队把这座城镇烧成灰烬那天留下的老兵。$B$B毒蛇女士Serpentia。$B$B领主Ta’jax。$B$B当年进攻时他们还是中尉。镇上燃起大火时，正是他们的战团扫过了街头。从那以后，这片废墟就一直由他们统治。$B$B要想让Tideblade失去对这里的掌控，这两个人必须倒下。没了他们的统领，纳迦会分裂成更小的族群，更容易被赶回海里去。$B$B纳迦统治这片废墟已经太久了。') ON DUPLICATE KEY UPDATE `Details_loc4` = VALUES(`Details_loc4`);
INSERT INTO `locales_quest` (`entry`, `Details_loc4`) VALUES (42092, '西边那个环形山你见过吧？就是被他们叫做星辰摇篮的那个。$B$B这名字取得可真够倒霉的，甚至有点浪漫。我可以向你保证，一块从天而降、把大地砸裂的石头，跟浪漫半点关系都没有。$B$B让我感兴趣的倒不是那个坑，而是坑之后来的东西——蓝龙。不是一两条路过，而是一整窝在撞击点上方盘旋，仿佛那里是座神龛。其中有一条尤其引起了我的注意。$B$B召星者。$B$B它巡视着环形山上空，把任何靠得太近的东西都赶走。冒险者。学者。连纳迦都学会了绕道走。$B$B于是我们只剩下两种可能。$B$B要么是陨石把龙引到了这里……要么是龙自己让它掉了下来。$B$B哪一种都让我坐立不安。$B$B去星辰摇篮杀掉那头叫召星者的龙。它一死，我们也许就能弄清楚那些龙到底在那里守着什么。') ON DUPLICATE KEY UPDATE `Details_loc4` = VALUES(`Details_loc4`);
INSERT INTO `locales_quest` (`entry`, `Details_loc4`) VALUES (42093, '纳瓦利斯哨站看着平静，可平静的地方照样需要守卫。哨兵们日夜在林中巡逻。多数人只看见她们的战刃，却忘了这门手艺的另一半。$B$B弓。$B$B<Elendon 从工作台上拿起一捆还没做完的箭。>$B$B好箭可不是随便削两根就行。笔直的箭杆、配重得当的箭头……还有合适的箭羽。没有对的羽毛，再好的箭也会飞歪。往常我们从卡多雷腹地运材料进来，可通往这片海岸的补给线……不太靠得住。$B$B好在附近的森林里有别的选择。Azureshimmer 角鹰兽就栖息在周边的悬崖和高枝上。它们的羽毛轻、结实，飞行时格外稳定，拿来做哨兵的箭再合适不过。$B$B我只要一小把。给我收集十二根羽毛来。尽量别伤着多余的角鹰兽——它们是骄傲的生灵，在这片海岸上住得比我们久得多。') ON DUPLICATE KEY UPDATE `Details_loc4` = VALUES(`Details_loc4`);
INSERT INTO `locales_quest` (`entry`, `Details_loc4`) VALUES (42094, '荒野会对懂得倾听的人低语。$B$B多数人听见的是林间的风。树叶的沙沙声。沉睡森林安静的呼吸。$B$B而近来……森林一直不得安宁。$B$B往南有一处曾被称为月之林地的地方。那是德鲁伊研习睡眠与梦境轮回、探究翡翠梦境隐秘路径的静谧圣所。$B$B可如今住在那里的人不再遵循塞纳留斯的教诲。$B$B他们自称飞蛾的仆从。$B$B古怪的仪式。扭曲的梦境。他们开始按自己的设想重塑荒野，无视自玛洛恩之子最初的教诲以来一直指引德鲁伊的平衡之道。$B$B这样的狂妄终将招致毁灭。$B$B去月之林地削减他们的数量。杀掉八名飞蛾德鲁伊、八名 Lo’sho 信徒、八名清醒梦境守护者和八名清醒梦境潜伏者。$B$B也许当他们倒下足够多人之后，剩下的会记起身为德鲁伊意味着什么。') ON DUPLICATE KEY UPDATE `Details_loc4` = VALUES(`Details_loc4`);
INSERT INTO `locales_quest` (`entry`, `Details_loc4`) VALUES (42096, '你在月之林地看到的腐化只是开始。$B$B往北是艾纳兰，一座神圣的村庄，过去由既敬森林又敬月亮的德鲁伊照料。$B$B如今它正在溃烂。$B$B那些背弃塞纳留斯教诲的德鲁伊把影响扩散到了那里。他们的仪式扭曲大地，腐化之物如今在古树下游荡。$B$B连我的一些亲族也堕落了。$B$B被他们魔法腐化的树妖如今自称腐烂姐妹。萨特在暗影中低语，喂养着蔓延整片林地的疯狂。$B$B而那些远古守护者……森林伟大的守卫者……已经开始腐烂，却仍在行走。$B$B不能再这样下去了。$B$B去艾纳兰，净化那片林地。杀掉十名腐烂姐妹、十名低语萨特和五名腐烂远古守护者。') ON DUPLICATE KEY UPDATE `Details_loc4` = VALUES(`Details_loc4`);
INSERT INTO `locales_quest` (`entry`, `Details_loc4`) VALUES (42097, '搞出这场腐化的德鲁伊不只他们自己。他们的首领是一位林地守护者，名叫 Krothis。$B$B他曾是这片土地上德鲁伊们敬重的人物。森林的守护者，耐心而睿智。荒野失衡之时，许多人来向他求教。$B$B如今他侍奉着另一位。你交手过的那些德鲁伊提到一个名号：Mothshroud。$B$B很久以前，在这些林地大多沉寂下来之前，一位大德鲁伊指引着这一带的德鲁伊。他是梦境、黑夜，以及清醒与翡翠梦境之间那些隐秘地带的导师。他走过极少有德鲁伊敢去研究的路径。$B$B最终，那些路径把他带去了一个我们再也无法跟随的地方。他消失了，林地也慢慢回到更朴素的教义。$B$B可如今他的阴影似乎回来了。Krothis 现在侍奉 Mothshroud，在各处林地执行他的意志。$B$B要让森林痊愈，Krothis 必须倒下。') ON DUPLICATE KEY UPDATE `Details_loc4` = VALUES(`Details_loc4`);
INSERT INTO `locales_quest` (`entry`, `Details_loc4`) VALUES (42100, '$C，你也许正是我需要的人。今天是纪念日，暴风城的居民们会向王国里的弱者、老人以及其他所有不幸的人捐赠财物，以表达对大主教阿隆索斯·法奥——北郡修道院前任主教的敬意。我正从湖畔镇赶来，把镇民们无私的捐赠送往暴风城，可一群可怕的豺狼人洗劫了我的马车。所有的衣服、食物和玩具不是被他们弄坏，就是被彻底毁掉了。$B$B两手空空，我几乎绝望了。但就像法奥大主教亲自听到了我的苦楚一般，我瞥见附近闪着一道微光。我循着光亮看去，发现了一片三叶草地，这分明是法奥善意的迹象！据说沿着三叶草指引的道路走，就能走上幸运之路。$B$B也许这就是我困境的答案。你愿意为暴风城那些需要帮助的人伸出援手吗？') ON DUPLICATE KEY UPDATE `Details_loc4` = VALUES(`Details_loc4`);
INSERT INTO `locales_quest` (`entry`, `Details_loc4`) VALUES (42101, '你好，旅行者。你或许正是能解我眼下困境的人。我们每天都感谢大地母亲的恩赐，而今天是个特别的日子。所有居住在莫高雷这片应许之地的部族都会齐聚雷霆崖，献上一场盛大的宴会，用歌声和舞蹈庆祝大地母亲赐予我们的丰饶。可遗憾的是，我原打算用来运送这批募捐物资的马车被当地的豺狼人洗劫了。所有的衣服、食物和乐器都被他们毁得一干二净，如今我们只能靠仅剩的东西勉强凑合。$B$B不过，事情还有一线希望。当我在村里四处查看还剩下些什么的时候，眼角余光瞥见一个精灵的身影朝雷霆崖跑去。可等我再看第二眼时，却只看到一片三叶草地。$C，我相信这是大地母亲给我的启示。沿着三叶草指引的道路走下去，我们或许还来得及挽救这场宴会。') ON DUPLICATE KEY UPDATE `Details_loc4` = VALUES(`Details_loc4`);
INSERT INTO `locales_quest` (`entry`, `ObjectiveText1_loc4`) VALUES (41911, '已找到Narlan') ON DUPLICATE KEY UPDATE `ObjectiveText1_loc4` = VALUES(`ObjectiveText1_loc4`);
