INSERT INTO `locales_quest` (`entry`, `Objectives_loc4`) VALUES (41906, '从黑铁营地里救出被绑架的高等精灵一家。') ON DUPLICATE KEY UPDATE `Objectives_loc4` = VALUES(`Objectives_loc4`);
INSERT INTO `locales_quest` (`entry`, `Objectives_loc4`) VALUES (41911, '在莫洛加村北面的前哨据点找到Naran，然后回到莫洛加村向Arlia复命。') ON DUPLICATE KEY UPDATE `Objectives_loc4` = VALUES(`Objectives_loc4`);
INSERT INTO `locales_quest` (`entry`, `Objectives_loc4`) VALUES (41914, '搜寻德莱尼阴谋者，把他们的死亡证明带回莫洛加村交给Arlia。') ON DUPLICATE KEY UPDATE `Objectives_loc4` = VALUES(`Objectives_loc4`);
INSERT INTO `locales_quest` (`entry`, `Objectives_loc4`) VALUES (41915, '在莫洛加村就你新发现的真相质问 Morogai Kla。') ON DUPLICATE KEY UPDATE `Objectives_loc4` = VALUES(`Objectives_loc4`);
INSERT INTO `locales_quest` (`entry`, `Objectives_loc4`) VALUES (41916, '找到Elder Bhurobi并阻止他的圣战。事成之后回到Morogai Kla那里复命。') ON DUPLICATE KEY UPDATE `Objectives_loc4` = VALUES(`Objectives_loc4`);
INSERT INTO `locales_quest` (`entry`, `Objectives_loc4`) VALUES (41920, '找到Maghan丢失的货物，把它带给莫洛加村的Pli。') ON DUPLICATE KEY UPDATE `Objectives_loc4` = VALUES(`Objectives_loc4`);
INSERT INTO `locales_quest` (`entry`, `Objectives_loc4`) VALUES (41928, '把地穴领主的召唤交给一位强大的圣光使用者。') ON DUPLICATE KEY UPDATE `Objectives_loc4` = VALUES(`Objectives_loc4`);
INSERT INTO `locales_quest` (`entry`, `Objectives_loc4`) VALUES (41930, '在艾萨拉的乌索克之喉，向Narkogg the Dark出示你在木喉要塞杀死Karrsh the Sentinel的证据。') ON DUPLICATE KEY UPDATE `Objectives_loc4` = VALUES(`Objectives_loc4`);
INSERT INTO `locales_quest` (`entry`, `Objectives_loc4`) VALUES (41931, '在木喉要塞内从Withermaw萨满身上收集Withermaw图腾，把它们带给艾萨拉乌索克之喉的Narkogg the Dark。') ON DUPLICATE KEY UPDATE `Objectives_loc4` = VALUES(`Objectives_loc4`);
INSERT INTO `locales_quest` (`entry`, `Objectives_loc4`) VALUES (41932, '艾萨拉乌索克之喉的 Narkogg the Dark 需要特定的材料来调配净化药膏。把材料交给他。') ON DUPLICATE KEY UPDATE `Objectives_loc4` = VALUES(`Objectives_loc4`);
INSERT INTO `locales_quest` (`entry`, `Objectives_loc4`) VALUES (41933, '从木喉要塞内取回Narkogg的药袋和腐臭之花，交给艾萨拉乌索克之喉的Narkogg the Dark。') ON DUPLICATE KEY UPDATE `Objectives_loc4` = VALUES(`Objectives_loc4`);
INSERT INTO `locales_quest` (`entry`, `Objectives_loc4`) VALUES (41934, '在木喉要塞杀死乌索尔。事成后向艾萨拉乌索克之喉的Narkogg the Dark汇报。') ON DUPLICATE KEY UPDATE `Objectives_loc4` = VALUES(`Objectives_loc4`);
INSERT INTO `locales_quest` (`entry`, `Objectives_loc4`) VALUES (41935, '为复活术之仪祭找到一个用途。文中所提到的不朽存在，很可能就是游荡在艾泽拉斯的那些强大巨龙。') ON DUPLICATE KEY UPDATE `Objectives_loc4` = VALUES(`Objectives_loc4`);
INSERT INTO `locales_quest` (`entry`, `Objectives_loc4`) VALUES (41936, '把水晶交给一位强大的术士。') ON DUPLICATE KEY UPDATE `Objectives_loc4` = VALUES(`Objectives_loc4`);
INSERT INTO `locales_quest` (`entry`, `Objectives_loc4`) VALUES (41939, '驱逐风角峡谷内的元素首领，然后回到石爪山脉大地之环的 Shovu 那里复命。') ON DUPLICATE KEY UPDATE `Objectives_loc4` = VALUES(`Objectives_loc4`);
INSERT INTO `locales_quest` (`entry`, `Objectives_loc4`) VALUES (41940, '把阿拉希高地四座禁锢法阵中各类元素生物身上完好的核心带给外禁锢法阵附近的Grakk Windtamer。') ON DUPLICATE KEY UPDATE `Objectives_loc4` = VALUES(`Objectives_loc4`);
INSERT INTO `locales_quest` (`entry`, `Objectives_loc4`) VALUES (41941, '大地之环的Firespeaker Bewali要你把安戈洛环形山火羽山一带的火山土壤带给东瘟疫之地圣光之愿礼拜堂的雷布拉特·碎地者。') ON DUPLICATE KEY UPDATE `Objectives_loc4` = VALUES(`Objectives_loc4`);
INSERT INTO `locales_quest` (`entry`, `Objectives_loc4`) VALUES (41942, '把孢子覆盖的骸骨和一株扭曲的树苗交给东瘟疫之地圣光之愿礼拜堂的雷布拉特·碎地者。') ON DUPLICATE KEY UPDATE `Objectives_loc4` = VALUES(`Objectives_loc4`);
INSERT INTO `locales_quest` (`entry`, `Objectives_loc4`) VALUES (41943, '净化玛拉顿内部受腐化的水源，并除掉腐化的源头，然后回到石爪山脉大地之环的 Ohona Riverbend 那里。') ON DUPLICATE KEY UPDATE `Objectives_loc4` = VALUES(`Objectives_loc4`);
INSERT INTO `locales_quest` (`entry`, `Objectives_loc4`) VALUES (41945, '莫洛加村的Fena Ma’dar想要珀爪的脑浆来治她的头痛。') ON DUPLICATE KEY UPDATE `Objectives_loc4` = VALUES(`Objectives_loc4`);
INSERT INTO `locales_quest` (`entry`, `Objectives_loc4`) VALUES (41951, '去莫洛加村南边与商人Maghan谈谈水晶箱的事。') ON DUPLICATE KEY UPDATE `Objectives_loc4` = VALUES(`Objectives_loc4`);
INSERT INTO `locales_quest` (`entry`, `Objectives_loc4`) VALUES (41953, '进入木喉要塞取回被腐化的德拉诺水晶。如果成功，把它们交给月语海岸莫洛加村的Riftmaster Ral’pekta。') ON DUPLICATE KEY UPDATE `Objectives_loc4` = VALUES(`Objectives_loc4`);
INSERT INTO `locales_quest` (`entry`, `Objectives_loc4`) VALUES (41956, '找到绿爪部族、冬泉部族与木喉部族。三处都找到后，回到艾萨拉乌索克之喉的 Nathok 那里。') ON DUPLICATE KEY UPDATE `Objectives_loc4` = VALUES(`Objectives_loc4`);
INSERT INTO `locales_quest` (`entry`, `Objectives_loc4`) VALUES (41958, '在悲伤沼泽寻找一条愿意合作的绿龙，向它打听灵魂之笛。') ON DUPLICATE KEY UPDATE `Objectives_loc4` = VALUES(`Objectives_loc4`);
INSERT INTO `locales_quest` (`entry`, `Objectives_loc4`) VALUES (41959, '找出绿龙叛徒 Insomnius。Itharius 说他如今住在 Gilijim 岛以北的岛上。') ON DUPLICATE KEY UPDATE `Objectives_loc4` = VALUES(`Objectives_loc4`);
