INSERT INTO `locales_quest` (`entry`, `Objectives_loc4`) VALUES (41962, '与泰达希尔海岸边的远古守护者Fangorn交谈。想听懂他那晦涩难解的话语，得先向月光林地的德鲁伊们求教。') ON DUPLICATE KEY UPDATE `Objectives_loc4` = VALUES(`Objectives_loc4`);
