INSERT INTO `locales_quest` (`entry`, `Objectives_loc4`) VALUES (42100, '沿着三叶草地指引的道路前进，帮Raymond摆脱困境！他在艾尔文森林的闪金镇等着你。') ON DUPLICATE KEY UPDATE `Objectives_loc4` = VALUES(`Objectives_loc4`);
INSERT INTO `locales_quest` (`entry`, `Objectives_loc4`) VALUES (42101, '沿着三叶草地指引的道路前进，帮Hehfani摆脱困境！她在莫高雷的血蹄村等着你。') ON DUPLICATE KEY UPDATE `Objectives_loc4` = VALUES(`Objectives_loc4`);
INSERT INTO `locales_quest` (`entry`, `OfferRewardText_loc4`) VALUES (41304, '<Tacknazz读着你从地精身上找到的那份契约。他越读，他那绿色的皮肤就变得越红。>$B$B噢，那些背后捅刀、啃痂皮的穴居怪！离开风险投资公司是Nert这辈子做过最正确的决定，我早就受够他们那些见不得人的手段了。我不仅丢了所有珍贵的珠宝，还失去了最好的承包商，要找个替代的人得花上好久！噢，Grizzby，你这老混蛋，你本该有更好的下场，好得多……') ON DUPLICATE KEY UPDATE `OfferRewardText_loc4` = VALUES(`OfferRewardText_loc4`);
INSERT INTO `locales_quest` (`entry`, `OfferRewardText_loc4`) VALUES (41340, '$C，干得好。看到你这么迅速就完成了任务，我就更不必担心接下来要请你做的事了。你或许不知道，我和我的同胞都是玛洛恩的后裔。正是他与月神伊露恩的结合，孕育了我们的父神塞纳留斯——而他又创造了我们。这件事不仅关乎海加尔山的安危，关乎我的家族，更关乎整个艾泽拉斯。') ON DUPLICATE KEY UPDATE `OfferRewardText_loc4` = VALUES(`OfferRewardText_loc4`);
INSERT INTO `locales_quest` (`entry`, `OfferRewardText_loc4`) VALUES (41577, '你可以从这些奖励中选择一件：Felforged Nathrezan Veil、Felforged Nathrezan Circlet、Felforged Nathrezan Aureole') ON DUPLICATE KEY UPDATE `OfferRewardText_loc4` = VALUES(`OfferRewardText_loc4`);
